{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-01a1Bx/src/merge.js","content":"import { diff } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Build the list of regions covering the whole base document: stable
 * regions (untouched by any change) and merged regions (covering one or
 * more overlapping changes from either side).
 */
function buildRegions(base, mineChanges, theirsChanges) {
  const tagged = [
    ...mineChanges.map(c => ({ ...c, side: 'mine' })),
    ...theirsChanges.map(c => ({ ...c, side: 'theirs' })),
  ]
  tagged.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let pos = 0
  let k = 0
  while (k < tagged.length) {
    const start = tagged[k].baseStart
    let end = tagged[k].baseEnd
    const changes = [tagged[k]]
    k++
    while (k < tagged.length && tagged[k].baseStart <= end) {
      end = Math.max(end, tagged[k].baseEnd)
      changes.push(tagged[k])
      k++
    }
    if (start > pos) {
      regions.push({ stable: true, baseStart: pos, baseEnd: start })
    }
    regions.push({ stable: false, baseStart: start, baseEnd: end, changes })
    pos = end
  }
  if (pos < base.length) {
    regions.push({ stable: true, baseStart: pos, baseEnd: base.length })
  }
  return regions
}

/** Reconstruct a side's lines across `[start, end)`, filling gaps between
 * that side's own changes (and before/after them) with the unchanged base
 * lines. */
function buildSide(base, changes, start, end) {
  const result = []
  let pos = start
  for (const c of changes) {
    result.push(...base.slice(pos, c.baseStart))
    result.push(...c.lines)
    pos = c.baseEnd
  }
  result.push(...base.slice(pos, end))
  return result
}

/**
 * Compute the full list of regions with their resolutions for `merge`,
 * `merge2` and `regions` to share.
 *
 * Each region is one of:
 *   { kind: 'stable', lines }
 *   { kind: 'mine' | 'theirs' | 'both', lines }
 *   { kind: 'conflict', mine, base, theirs }
 */
export function computeRegions(mine, base, theirs) {
  const mineChanges = diff(base, mine)
  const theirsChanges = diff(base, theirs)
  const regions = buildRegions(base, mineChanges, theirsChanges)

  return regions.map(region => {
    if (region.stable) {
      return { kind: 'stable', lines: base.slice(region.baseStart, region.baseEnd) }
    }
    const mineOwn = region.changes.filter(c => c.side === 'mine')
    const theirsOwn = region.changes.filter(c => c.side === 'theirs')
    const mineLines = buildSide(base, mineOwn, region.baseStart, region.baseEnd)
    const theirsLines = buildSide(base, theirsOwn, region.baseStart, region.baseEnd)
    const baseLines = base.slice(region.baseStart, region.baseEnd)

    if (arraysEqual(mineLines, theirsLines)) {
      return { kind: 'both', lines: mineLines }
    }
    if (arraysEqual(mineLines, baseLines)) {
      return { kind: 'theirs', lines: theirsLines }
    }
    if (arraysEqual(theirsLines, baseLines)) {
      return { kind: 'mine', lines: mineLines }
    }
    return { kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines }
  })
}
"}

