{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-01a1Bx/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { computeRegions } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function splitParts(lines) {
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }
  return parts
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('error: usage: cli.js merge|merge2|regions')
  }
  const mode = args[0]

  const text = readStdin()
  const lines = splitLines(text)
  const parts = splitParts(lines)
  if (parts.length !== 3) {
    fail('error: expected three parts separated by %%%')
  }
  const [mine, base, theirs] = parts

  const regions = computeRegions(mine, base, theirs)

  let conflict = false
  const out = []

  if (mode === 'regions') {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
      } else {
        out.push(`${region.kind} ${region.lines.length}`)
      }
    }
  } else {
    for (const region of regions) {
      if (region.kind === 'conflict') {
        conflict = true
        out.push('<<<<<<< mine')
        for (const line of region.mine) out.push(line)
        if (mode === 'merge') {
          out.push('||||||| base')
          for (const line of region.base) out.push(line)
        }
        out.push('=======')
        for (const line of region.theirs) out.push(line)
        out.push('>>>>>>> theirs')
      } else {
        for (const line of region.lines) out.push(line)
      }
    }
  }

  const text_out = out.length > 0 ? `${out.join('\n')}\n` : ''
  process.stdout.write(text_out)
  process.exit(conflict ? 1 : 0)
}

main()
"}

