const TOKEN_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function parseInt_(str, min, fieldName, line) {
  if (!INT_RE.test(str) || BigInt(str) < min) {
    throw new ParseError(line, `${fieldName} must be an integer of at least ${min}`)
  }
  return BigInt(str)
}

/**
 * Parses and validates the whole limiter file, returning:
 *   { policies: Map<name, policy>, routes: [{ prefix, policyNames }], events: [{ tick, key }] }
 * Throws ParseError on the first problem, per the spec's line-by-line reasons.
 */
export function parseLimiterFile(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []

  let eventsStarted = false
  let lastTick = null

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive !== 'bucket' && directive !== 'window' && directive !== 'route' && directive !== 'event') {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }

    if (directive !== 'event' && eventsStarted) {
      throw new ParseError(lineNo, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (words.length !== 5) {
        throw new ParseError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityStr, refillStr, perStr] = words
      if (!TOKEN_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const capacity = parseInt_(capacityStr, 1n, 'capacity', lineNo)
      const refill = parseInt_(refillStr, 0n, 'refill', lineNo)
      const per = parseInt_(perStr, 1n, 'per', lineNo)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (words.length !== 4) {
        throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
      }
      const [, name, limitStr, spanStr] = words
      if (!TOKEN_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const limit = parseInt_(limitStr, 0n, 'limit', lineNo)
      const span = parseInt_(spanStr, 1n, 'span', lineNo)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(name, limit, span))
    } else if (directive === 'route') {
      if (words.length < 3) {
        throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = words[1]
      const policyNames = words.slice(2)
      if (!TOKEN_RE.test(prefix)) throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
      for (const name of policyNames) {
        if (!policies.has(name)) throw new ParseError(lineNo, `unknown policy ${name}`)
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
      if (words.length !== 3) {
        throw new ParseError(lineNo, 'expected event <tick> <key>')
      }
      const [, tickStr, key] = words
      const tick = parseInt_(tickStr, 0n, 'tick', lineNo)
      if (!TOKEN_RE.test(key)) throw new ParseError(lineNo, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      eventsStarted = true
      events.push({ tick, key })
    }
  }

  return { policies, routes, events }
}
