 * Resolves each event's route (longest matching prefix, or none) and
 * simulates the policies on that route in order, producing a verdict per
 * event.
 */
export function simulate({ policies, routes, events }) {
  function findRoute(key) {
    let best = null
    for (const route of routes) {
      if (key.startsWith(route.prefix)) {
        if (best === null || route.prefix.length > best.prefix.length) best = route
      }
    }
    return best
  }

  const verdicts = []
  for (const { tick, key } of events) {
    const route = findRoute(key)
    if (route === null) {
      verdicts.push({ tick, key, allowed: true, denyPolicy: null })
      continue
    }
    const routePolicies = route.policyNames.map((name) => policies.get(name))
    for (const policy of routePolicies) policy.advance(key, tick)

    let denyPolicy = null
    for (let i = 0; i < routePolicies.length; i++) {
      if (!routePolicies[i].allow(key)) {
        denyPolicy = route.policyNames[i]
        break
      }
    }

    if (denyPolicy === null) {
      for (const policy of routePolicies) {
        if (policy instanceof (routePolicies[0].constructor)) {
          // no-op, placeholder to keep structure clear
        }
      }
      for (const policy of routePolicies) {
        if (policy.record.length === 2) {
          policy.record(key, tick)
        } else {
          policy.record(key)
        }
      }
      verdicts.push({ tick, key, allowed: true, denyPolicy: null })
    } else {
      verdicts.push({ tick, key, allowed: false, denyPolicy })
    }
  }
  return verdicts
}
"}

