 * Parses a limiter file into a config of policies, routes and events.
 */

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

class ParseError extends Error {
  constructor(line, message) {
    super(`line ${line}: ${message}`)
    this.line = line
  }
}

function parseInt_(token, field, least) {
  if (!INT_RE.test(token) || BigInt(token) < BigInt(least)) {
    throw new Error(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(token)
}

function checkName(token, kind) {
  if (!NAME_RE.test(token)) {
    throw new Error(`invalid ${kind} ${token}`)
  }
}

export function parse(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const policies = new Map()
  const routes = []
  const routesByPrefix = new Map()
  const events = []
  let sawEvent = false
  let lastTick = null

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]
    const rest = tokens.slice(1)

    try {
      if (word === 'bucket') {
        if (sawEvent) throw new Error('declarations must come before the first event')
        if (rest.length !== 4) throw new Error('expected bucket <name> <capacity> <refill> <per>')
        const [name, capTok, refillTok, perTok] = rest
        checkName(name, 'policy name')
        const capacity = parseInt_(capTok, 'capacity', 1)
        const refill = parseInt_(refillTok, 'refill', 0)
        const per = parseInt_(perTok, 'per', 1)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        policies.set(name, { type: 'bucket', capacity, refill, per, states: new Map() })
      } else if (word === 'window') {
        if (sawEvent) throw new Error('declarations must come before the first event')
        if (rest.length !== 3) throw new Error('expected window <name> <limit> <span>')
        const [name, limitTok, spanTok] = rest
        checkName(name, 'policy name')
        const limit = parseInt_(limitTok, 'limit', 0)
        const span = parseInt_(spanTok, 'span', 1)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        policies.set(name, { type: 'window', limit, span, states: new Map() })
      } else if (word === 'route') {
        if (sawEvent) throw new Error('declarations must come before the first event')
        if (rest.length < 2) throw new Error('expected route <prefix> <policy>...')
        const [prefix, ...policyNames] = rest
        if (!NAME_RE.test(prefix)) throw new Error(`invalid route prefix ${prefix}`)
        for (const pname of policyNames) {
          if (!policies.has(pname)) throw new Error(`unknown policy ${pname}`)
        }
        if (routesByPrefix.has(prefix)) throw new Error(`prefix ${prefix} is routed twice`)
        const route = { prefix, policies: policyNames }
        routesByPrefix.set(prefix, route)
        routes.push(route)
      } else if (word === 'event') {
        if (rest.length !== 2) throw new Error('expected event <tick> <key>')
        const [tickTok, key] = rest
        const tick = parseInt_(tickTok, 'tick', 0)
        if (!NAME_RE.test(key)) throw new Error(`invalid key ${key}`)
        if (lastTick !== null && tick < lastTick) {
          throw new Error(`tick ${tick} is before tick ${lastTick}`)
        }
        lastTick = tick
        sawEvent = true
        events.push({ tick, key, line: lineNo })
      } else {
        throw new Error(`unknown directive ${word}`)
      }
    } catch (err) {
      throw new ParseError(lineNo, err.message)
    }
  }

  routes.sort((a, b) => b.prefix.length - a.prefix.length)

  return { policies, routes, events }
}

export { ParseError }
"}

