{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-2iBW37/src/simulate.js","content":"import {
  advanceBucket,
  bucketAllows,
  bucketRecord,
  advanceWindow,
  windowAllows,
  windowRecord,
} from './policy.js'

function findRoute(routes, key) {
  for (const route of routes) {
    if (key.startsWith(route.prefix)) return route
  }
  return null
}

export function simulate(config) {
  const { policies, routes, events } = config
  const results = []

  for (const event of events) {
    const { tick, key } = event
    const route = findRoute(routes, key)

    if (!route || route.policies.length === 0) {
      results.push({ tick, key, allowed: true, deniedBy: null })
      continue
    }

    const states = []
    const allows = []

    for (const pname of route.policies) {
      const policy = policies.get(pname)
      let state
      if (policy.type === 'bucket') {
        state = advanceBucket(policy, key, tick)
        allows.push(bucketAllows(policy, state))
      } else {
        state = advanceWindow(policy, key, tick)
        allows.push(windowAllows(policy, state))
      }
      states.push({ policy, state })
    }

    const allAllow = allows.every(Boolean)

    if (allAllow) {
      for (const { policy, state } of states) {
        if (policy.type === 'bucket') {
          bucketRecord(policy, state)
        } else {
          windowRecord(state, tick)
        }
      }
      results.push({ tick, key, allowed: true, deniedBy: null })
    } else {
      const idx = allows.findIndex((a) => !a)
      results.push({ tick, key, allowed: false, deniedBy: route.policies[idx] })
    }
  }

  return results
}
"}

