function scanPunct(s) {
  const pos = s.pos()
  const c0 = s.peek()
  const c1 = s.peek(1)
  const two = (c0 ?? '') + (c1 ?? '')
  if (PUNCT2.includes(two)) {
    s.advance()
    s.advance()
    return { kind: 'punct', line: pos.line, col: pos.col, text: two }
  }
  if (PUNCT1.has(c0)) {
    s.advance()
    return { kind: 'punct', line: pos.line, col: pos.col, text: c0 }
  }
  throw err(pos, `unexpected character ${c0}`)
}

export function tokenize(input) {
  const s = new Scanner(input)
  const tokens = []
  while (true) {
    skipTrivia(s)
    if (s.atEnd()) break
    const c = s.peek()
    let tok
    if (c === 'r' && s.peek(1) === '"') {
      tok = scanRawString(s)
    } else if (isIdentStart(c)) {
      tok = scanIdent(s)
    } else if (isDecDigit(c)) {
      tok = scanNumber(s)
    } else if (c === '"') {
      tok = scanString(s)
    } else {
      tok = scanPunct(s)
    }
    tokens.push(tok)
  }
  return tokens
}
"}

