/**
 * Split raw stdin text into lines, dropping the single empty tail a
 * trailing newline leaves.
 * @param {string} input
 * @returns {string[]}
 */
function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }
  return lines
}

/**
 * Split the input into exactly three documents (mine, base, theirs),
 * separated by lines that are exactly `%%%`.
 * @param {string} input
 * @returns {string[][] | null} null when the input does not hold exactly
 * three parts.
 */
export function parseInput(input) {
  const lines = splitLines(input)
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }
  if (parts.length !== 3) {
    return null
  }
  return parts
}
"}

