{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-JrF6ay/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { parseInput } from './parse.js'
import { buildRegions } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  while (true) {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const input = readStdin()
  const parts = parseInput(input)
  if (parts === null) {
    fail('expected three parts separated by %%%')
    return
  }
  const [mine, base, theirs] = parts

  const regions = buildRegions(mine, base, theirs)
  const hasConflict = regions.some(r => r.kind === 'conflict')

  const out = []
  if (mode === 'regions') {
    for (const region of regions) {
      switch (region.kind) {
        case 'stable':
          out.push(`stable ${region.lines.length}`)
          break
        case 'mine':
          out.push(`mine ${region.lines.length}`)
          break
        case 'theirs':
          out.push(`theirs ${region.lines.length}`)
          break
        case 'both':
          out.push(`both ${region.lines.length}`)
          break
        case 'conflict':
          out.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
          break
      }
    }
  } else {
    const includeBase = mode === 'merge'
    for (const region of regions) {
      if (region.kind === 'conflict') {
        out.push('<<<<<<< mine')
        out.push(...region.mineLines)
        if (includeBase) {
          out.push('||||||| base')
          out.push(...region.baseLines)
        }
        out.push('=======')
        out.push(...region.theirsLines)
        out.push('>>>>>>> theirs')
      } else {
        out.push(...region.lines)
      }
    }
  }

  const text = out.length > 0 ? `${out.join('\n')}\n` : ''
  process.stdout.write(text)
  process.exit(hasConflict ? 1 : 0)
}

main()
"}

