      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const input = readStdin()
  const parts = parseInput(input)
  if (parts === null) {
    fail('expected three parts separated by %%%')
    return
  }
  const [mine, base, theirs] = parts

  const regions = buildRegions(mine, base, theirs)
  const hasConflict = regions.some(r => r.kind === 'conflict')

  const out = []
  if (mode === 'regions') {
    for (const region of regions) {
      switch (region.kind) {
