export class LexError extends Error {}

export function tokenize(text) {
  const tokens = []
  let i = 0
  const n = text.length
  while (i < n) {
    const ch = text[i]
    if (ch === ' ' || ch === '\t') {
      i += 1
      continue
    }
    if (ch >= '0' && ch <= '9') {
      let j = i + 1
      while (j < n && text[j] >= '0' && text[j] <= '9') j += 1
      if (text[j] === '.' && text[j + 1] >= '0' && text[j + 1] <= '9') {
        j += 1
        while (j < n && text[j] >= '0' && text[j] <= '9') j += 1
      }
      tokens.push({ type: 'num', value: text.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < n && /[A-Za-z0-9]/.test(text[j])) j += 1
      tokens.push({ type: 'word', value: text.slice(i, j) })
      i = j
      continue
    }
    if (ch === '(') { tokens.push({ type: 'lparen' }); i += 1; continue }
    if (ch === ')') { tokens.push({ type: 'rparen' }); i += 1; continue }
    if (ch === ',') { tokens.push({ type: 'comma' }); i += 1; continue }
    if (ch === ':') { tokens.push({ type: 'colon' }); i += 1; continue }
    if (ch === '^') { tokens.push({ type: 'op', value: '^' }); i += 1; continue }
    if (ch === '*') { tokens.push({ type: 'op', value: '*' }); i += 1; continue }
    if (ch === '/') { tokens.push({ type: 'op', value: '/' }); i += 1; continue }
    if (ch === '+') { tokens.push({ type: 'op', value: '+' }); i += 1; continue }
    if (ch === '-') { tokens.push({ type: 'op', value: '-' }); i += 1; continue }
    if (ch === '=') { tokens.push({ type: 'op', value: '=' }); i += 1; continue }
    if (ch === '<') {
      if (text[i + 1] === '=') { tokens.push({ type: 'op', value: '<=' }); i += 2; continue }
      if (text[i + 1] === '>') { tokens.push({ type: 'op', value: '<>' }); i += 2; continue }
      tokens.push({ type: 'op', value: '<' }); i += 1; continue
    }
