{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-LACBlq/src/engine.js","content":"import { parseFormula, ParseError, LexError } from './parser.js'
import { parseAddressWord, canonicalAddress } from './address.js'
import { mkNum, mkText, mkBool, mkErr, numOf, parseLiteral, compareValues } from './values.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const KNOWN_FUNCS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

export class Engine {
  constructor(cells) {
    this.cells = cells
    this.astCache = new Map() // canonical -> ast | null (null = parse error)
    this.valueCache = new Map() // canonical -> Value
    this.inProgress = new Set()
  }

  getAst(canonical) {
    if (this.astCache.has(canonical)) return this.astCache.get(canonical)
    const cell = this.cells.get(canonical)
    let ast = null
    if (cell && cell.content.startsWith('=')) {
      try {
        ast = parseFormula(cell.content.slice(1))
      } catch (e) {
        if (e instanceof ParseError || e instanceof LexError) {
          ast = null
        } else {
          throw e
        }
      }
    }
    this.astCache.set(canonical, ast)
    return ast
  }

  evaluateCell(canonical) {
    if (this.valueCache.has(canonical)) return this.valueCache.get(canonical)
    if (this.inProgress.has(canonical)) return mkErr('#CYCLE!')

    const cell = this.cells.get(canonical)
    let value
    if (!cell) {
      value = mkNum(0)
    } else if (cell.content.startsWith('=')) {
      this.inProgress.add(canonical)
      const ast = this.getAst(canonical)
      if (ast === null) {
        value = mkErr('#ERR!')
      } else {
        value = this.evalExpr(ast)
      }
      this.inProgress.delete(canonical)
    } else {
      value = parseLiteral(cell.content)
    }
    this.valueCache.set(canonical, value)
    return value
  }

  // Evaluate a Range node's endpoints; returns list of canonical addresses in
  // ascending column then row order, or null if either endpoint is not
  // addressable.
  expandRange(node) {
    const a = parseAddressWord(node.a)
    const b = parseAddressWord(node.b)
    if (!a.valid || !b.valid) return null
    const colMin = Math.min(a.col, b.col)
    const colMax = Math.max(a.col, b.col)
    const rowMin = Math.min(a.row, b.row)
    const rowMax = Math.max(a.row, b.row)
    const addrs = []
    for (let c = colMin; c <= colMax; c += 1) {
      for (let r = rowMin; r <= rowMax; r += 1) {
        addrs.push(canonicalAddress(c, r))
      }
    }
    return addrs
  }

  // Evaluate an argument that is used in a scalar (single-value) context
  // (ABS's argument, IF's arguments). A range contributes its cells in
  // order; if any errors, the first wins; otherwise the first cell's value
  // is used.
  evalScalarArg(node) {
    if (node.type === 'Range') {
      const addrs = this.expandRange(node)
      if (addrs === null) return mkErr('#REF!')
      const vals = addrs.map((a) => this.evaluateCell(a))
      for (const v of vals) if (v.type === 'err') return v
      return vals[0]
    }
    return this.evalExpr(node)
  }

  evalExpr(node) {
    switch (node.type) {
      case 'Num':
        return mkNum(node.value)
      case 'Bool':
        return mkBool(node.value)
      case 'Address': {
        const a = parseAddressWord(node.word)
        if (!a.valid) return mkErr('#REF!')
        return this.evaluateCell(canonicalAddress(a.col, a.row))
      }
      case 'UnaryOp': {
        const v = this.evalExpr(node.operand)
        if (v.type === 'err') return v
        const n = numOf(v)
        if (n === null) return mkErr('#VALUE!')
        const result = node.op === '-' ? -n : n
        if (!Number.isFinite(result)) return mkErr('#DIV/0!')
        return mkNum(result)
      }
      case 'BinOp': {
        const lv = this.evalExpr(node.left)
        if (lv.type === 'err') return lv
        const rv = this.evalExpr(node.right)
        if (rv.type === 'err') return rv
        if (COMPARISON_OPS.has(node.op)) {
          const cmp = compareValues(lv, rv)
          switch (node.op) {
            case '=': return mkBool(cmp === 0)
            case '<>': return mkBool(cmp !== 0)
            case '<': return mkBool(cmp < 0)
            case '<=': return mkBool(cmp <= 0)
            case '>': return mkBool(cmp > 0)
            case '>=': return mkBool(cmp >= 0)
            default: throw new Error('unreachable')
          }
        }
        const ln = numOf(lv)
        const rn = numOf(rv)
        if (ln === null || rn === null) return mkErr('#VALUE!')
        let result
        switch (node.op) {
          case '+': result = ln + rn; break
          case '-': result = ln - rn; break
          case '*': result = ln * rn; break
          case '/': result = ln / rn; break
          case '^': result = Math.pow(ln, rn); break
          default: throw new Error('unreachable')
        }
        if (!Number.isFinite(result)) return mkErr('#DIV/0!')
        return mkNum(result)
      }
      case 'Call':
        return this.evalCall(node)
      default:
        throw new Error(`unexpected node type ${node.type}`)
    }
  }

  evalCall(node) {
    const name = node.name
    if (!KNOWN_FUNCS.has(name)) return mkErr('#NAME?')

    const argc = node.args.length
    if (name === 'ABS' && argc !== 1) return mkErr('#ERR!')
    if (name === 'IF' && argc !== 3) return mkErr('#ERR!')
    if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name) && argc < 1) return mkErr('#ERR!')

    if (name === 'IF') {
      const condVal = this.evalScalarArg(node.args[0])
      if (condVal.type === 'err') return condVal
      let condBool
      if (condVal.type === 'bool') condBool = condVal.value
      else if (condVal.type === 'num') condBool = condVal.value !== 0
      else return mkErr('#VALUE!')
      return this.evalScalarArg(condBool ? node.args[1] : node.args[2])
    }

    if (name === 'ABS') {
      const v = this.evalScalarArg(node.args[0])
      if (v.type === 'err') return v
      const n = numOf(v)
      if (n === null) return mkErr('#VALUE!')
      const result = Math.abs(n)
      if (!Number.isFinite(result)) return mkErr('#DIV/0!')
      return mkNum(result)
    }

    // Aggregate functions: SUM, MIN, MAX, COUNT, AVG
    const allValues = []
    for (const argNode of node.args) {
      if (argNode.type === 'Range') {
        const addrs = this.expandRange(argNode)
        if (addrs === null) {
          allValues.push(mkErr('#REF!'))
        } else {
          for (const a of addrs) allValues.push(this.evaluateCell(a))
        }
      } else {
        allValues.push(this.evalExpr(argNode))
      }
    }
    for (const v of allValues) if (v.type === 'err') return v

    switch (name) {
      case 'SUM': {
        let sum = 0
        for (const v of allValues) {
          const n = numOf(v)
          if (n === null) return mkErr('#VALUE!')
          sum += n
        }
        if (!Number.isFinite(sum)) return mkErr('#DIV/0!')
        return mkNum(sum)
      }
      case 'AVG': {
        let sum = 0
        for (const v of allValues) {
          const n = numOf(v)
          if (n === null) return mkErr('#VALUE!')
          sum += n
        }
        const avg = sum / allValues.length
        if (!Number.isFinite(avg)) return mkErr('#DIV/0!')
        return mkNum(avg)
      }
      case 'MIN': {
        let best = null
        for (const v of allValues) {
          const n = numOf(v)
          if (n === null) return mkErr('#VALUE!')
          if (best === null || n < best) best = n
        }
        return mkNum(best)
      }
      case 'MAX': {
        let best = null
        for (const v of allValues) {
          const n = numOf(v)
          if (n === null) return mkErr('#VALUE!')
          if (best === null || n > best) best = n
        }
        return mkNum(best)
      }
      case 'COUNT': {
        let cnt = 0
        for (const v of allValues) if (v.type === 'num') cnt += 1
        return mkNum(cnt)
      }
      default:
        throw new Error('unreachable')
    }
  }

  // Purely structural: collect every distinct addressable cell named
  // directly by a cell's content, ranges expanded, in column-then-row order.
  collectDeps(canonical) {
    const cell = this.cells.get(canonical)
    const result = new Set()
    if (!cell || !cell.content.startsWith('=')) return []
    const ast = this.getAst(canonical)
    if (ast === null) return []
    this.walkDeps(ast, result)
    const list = [...result].map((s) => {
      const a = parseAddressWord(s)
      return { s, col: a.col, row: a.row }
    })
    list.sort((x, y) => (x.col - y.col) || (x.row - y.row))
    return list.map((x) => x.s)
  }

  walkDeps(node, result) {
    switch (node.type) {
      case 'Num':
      case 'Bool':
        return
      case 'Address': {
        const a = parseAddressWord(node.word)
        if (a.valid) result.add(canonicalAddress(a.col, a.row))
        return
      }
      case 'UnaryOp':
        this.walkDeps(node.operand, result)
        return
      case 'BinOp':
        this.walkDeps(node.left, result)
        this.walkDeps(node.right, result)
        return
      case 'Call':
        for (const argNode of node.args) {
          if (argNode.type === 'Range') {
            const addrs = this.expandRange(argNode)
            if (addrs !== null) for (const a of addrs) result.add(a)
          } else {
            this.walkDeps(argNode, result)
          }
        }
        return
      default:
        throw new Error(`unexpected node type ${node.type}`)
    }
  }
}
"}

