{"file_path":"./src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { parseDocuments } from './parse.js'
import { mergeDocuments } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let mine, base, theirs
  try {
    ;[mine, base, theirs] = parseDocuments(input)
  } catch (err) {
    fail(err.message)
  }

  const segments = mergeDocuments(mine, base, theirs)

  let conflict = false
  const out = []

  if (mode === 'regions') {
    for (const seg of segments) {
      if (seg.type === 'conflict') {
        conflict = true
        out.push(`conflict mine=${seg.mine.length} base=${seg.base.length} theirs=${seg.theirs.length}\n`)
      } else {
        out.push(`${seg.type} ${seg.lines.length}\n`)
      }
    }
  } else {
    for (const seg of segments) {
      if (seg.type === 'conflict') {
        conflict = true
        out.push('<<<<<<< mine\n')
        for (const line of seg.mine) out.push(`${line}\n`)
        if (mode === 'merge') {
          out.push('||||||| base\n')
          for (const line of seg.base) out.push(`${line}\n`)
        }
        out.push('=======\n')
        for (const line of seg.theirs) out.push(`${line}\n`)
        out.push('>>>>>>> theirs\n')
      } else {
        for (const line of seg.lines) out.push(`${line}\n`)
      }
    }
  }

  process.stdout.write(out.join(''))
  process.exit(conflict ? 1 : 0)
}

main()
"}

