function serialize(node, indentLevel) {
  const ind = '  '.repeat(indentLevel)
  const ind2 = '  '.repeat(indentLevel + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node.map)
      if (keys.length === 0) return '{}'
      const lines = keys.map(
        (k) => `${ind2}${JSON.stringify(k)}: ${serialize(node.map.get(k), indentLevel + 1)}`
      )
      return `{\n${lines.join(',\n')}\n${ind}}`
    }
    case 'arrayOfTables':
    case 'array': {
      const items = node.items
      if (items.length === 0) return '[]'
      const lines = items.map((it) => `${ind2}${serialize(it, indentLevel + 1)}`)
      return `[\n${lines.join(',\n')}\n${ind}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJson(root) {
  return `${serialize(root, 0)}\n`
}

function walkKeys(node, path, out) {
  if (node.kind === 'table') {
    for (const key of sortedKeys(node.map)) {
      const child = node.map.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      out.push(`${childPath} ${typeOf(child)}`)
      walkKeys(child, childPath, out)
    }
  } else if (node.kind === 'array' || node.kind === 'arrayOfTables') {
    node.items.forEach((item, i) => {
      const childPath = `${path}[${i}]`
      out.push(`${childPath} ${typeOf(item)}`)
      walkKeys(item, childPath, out)
    })
  }
}

export function toKeys(root) {
  const out = []
  walkKeys(root, '', out)
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}
"}

