/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import fs from 'node:fs'
import { scan, LexError } from './lexer.js'

const KIND_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = fs.readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = scan(input)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.line}:${err.col}: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  let out
  if (mode === 'tokens') {
    const lines = tokens.map((t) => {
      const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.text) : t.text
      return `${t.line}:${t.col} ${t.kind} ${body}`
    })
    out = lines.length ? lines.join('\n') + '\n' : ''
  } else {
    const counts = Object.fromEntries(KIND_ORDER.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind]++
    const lines = KIND_ORDER.map((k) => `${k} ${counts[k]}`)
    lines.push(`total ${tokens.length}`)
    out = lines.join('\n') + '\n'
  }

  process.stdout.write(out)
  process.exit(0)
