{"file_path":"src/uri.js","content":"/**
 * RFC 3986 generic-syntax parsing, normalization and reference resolution.
 */

export class UriError extends Error {}

const DEFAULT_PORTS = { http: '80', https: '443', ws: '80', wss: '443', ftp: '21' }

/** Parse a URI reference into its generic-syntax components. */
export function parseUriRef(s) {
  let hasScheme = false
  let scheme = ''
  let rest = s

  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (c === ':') {
      hasScheme = true
      scheme = s.slice(0, i)
      rest = s.slice(i + 1)
      break
    }
    if (c === '/' || c === '?' || c === '#') {
      rest = s
      break
    }
  }

  let hasAuthority = false
  let authorityStr = ''
  let afterAuthority = rest

  if (rest.startsWith('//')) {
    hasAuthority = true
    let end = rest.length
    for (let i = 2; i < rest.length; i++) {
      const c = rest[i]
      if (c === '/' || c === '?' || c === '#') {
        end = i
        break
      }
    }
    authorityStr = rest.slice(2, end)
    afterAuthority = rest.slice(end)
  }

  const qIdx = afterAuthority.indexOf('?')
  const hIdx = afterAuthority.indexOf('#')
  let pathEnd
  if (qIdx === -1 && hIdx === -1) pathEnd = afterAuthority.length
  else if (qIdx === -1) pathEnd = hIdx
  else if (hIdx === -1) pathEnd = qIdx
  else pathEnd = Math.min(qIdx, hIdx)

  const path = afterAuthority.slice(0, pathEnd)
  let remainder = afterAuthority.slice(pathEnd)

  let hasQuery = false
  let query = ''
  if (remainder.startsWith('?')) {
    hasQuery = true
    const h2 = remainder.indexOf('#')
    if (h2 === -1) {
      query = remainder.slice(1)
      remainder = ''
    } else {
      query = remainder.slice(1, h2)
      remainder = remainder.slice(h2)
    }
  }

  let hasFragment = false
  let fragment = ''
  if (remainder.startsWith('#')) {
    hasFragment = true
    fragment = remainder.slice(1)
  }

  let hasUserinfo = false
  let userinfo = ''
  let host = ''
  let hasPort = false
  let port = ''

  if (hasAuthority) {
    let r = authorityStr
    const at = r.lastIndexOf('@')
    if (at !== -1) {
      hasUserinfo = true
      userinfo = r.slice(0, at)
      r = r.slice(at + 1)
    }
    const bracket = r.lastIndexOf(']')
    const colon = r.indexOf(':', bracket + 1)
    if (colon !== -1) {
      hasPort = true
      port = r.slice(colon + 1)
      host = r.slice(0, colon)
    } else {
      host = r
    }
  }

  return { hasScheme, scheme, hasAuthority, hasUserinfo, userinfo, host, hasPort, port, path, hasQuery, query, hasFragment, fragment }
}

/** Serialize parsed components back into a URI reference string. */
export function serialize(t) {
  let out = ''
  if (t.hasScheme) out += t.scheme + ':'
  if (t.hasAuthority) {
    out += '//'
    if (t.hasUserinfo) out += t.userinfo + '@'
    out += t.host
    if (t.hasPort) out += ':' + t.port
  }
  out += t.path
  if (t.hasQuery) out += '?' + t.query
  if (t.hasFragment) out += '#' + t.fragment
  return out
}

function isHex(ch) {
  return /^[0-9a-fA-F]$/.test(ch)
}

function isUnreserved(ch) {
  return /^[A-Za-z0-9\-._~]$/.test(ch)
}

function percentNormalize(s, name) {
  let out = ''
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (c === '%') {
      const a = s[i + 1]
      const b = s[i + 2]
      if (a === undefined || b === undefined || !isHex(a) || !isHex(b)) {
        throw new UriError(`the ${name} has a truncated percent-encoding`)
      }
      const upper = (a + b).toUpperCase()
      const code = parseInt(upper, 16)
      const ch = String.fromCharCode(code)
      if (isUnreserved(ch)) out += ch
      else out += '%' + upper
      i += 2
    } else {
      out += c
    }
  }
  return out
}

function asciiLowerCase(s) {
  let out = ''
  for (const c of s) {
    const code = c.codePointAt(0)
    if (code >= 65 && code <= 90) out += String.fromCharCode(code + 32)
    else out += c
  }
  return out
}

/** Remove dot segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '/..') {
      input = '/'
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const match = /^\/?[^/]*/.exec(input)[0]
      input = input.slice(match.length)
      output += match
    }
  }
  return output
}

/** Normalize a parsed URI reference. Throws UriError on invalid percent-encodings. */
export function normalize(t) {
  const r = { ...t }
  if (r.hasScheme) r.scheme = asciiLowerCase(r.scheme)

  r.path = percentNormalize(r.path, 'path')
  if (r.hasUserinfo) r.userinfo = percentNormalize(r.userinfo, 'userinfo')
  if (r.hasAuthority) r.host = percentNormalize(r.host, 'host')
  if (r.hasQuery) r.query = percentNormalize(r.query, 'query')
  if (r.hasFragment) r.fragment = percentNormalize(r.fragment, 'fragment')

  if (r.hasAuthority) r.host = asciiLowerCase(r.host)

  if (r.hasPort) {
    const def = r.hasScheme ? DEFAULT_PORTS[r.scheme] : undefined
    if (r.port === '' || (def !== undefined && r.port === def)) {
      r.hasPort = false
      r.port = ''
    }
  }

  r.path = removeDotSegments(r.path)

  if (r.hasAuthority && r.path === '') r.path = '/'

  return r
}

function mergePaths(base, refPath) {
  if (base.hasAuthority && base.path === '') return '/' + refPath
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/** Resolve a reference against a base per RFC 3986 section 5.2.2, strict form. */
export function resolveRef(base, ref) {
  const t = {}

  if (ref.hasScheme) {
    t.hasScheme = true
    t.scheme = ref.scheme
    t.hasAuthority = ref.hasAuthority
    t.hasUserinfo = ref.hasUserinfo
    t.userinfo = ref.userinfo
    t.host = ref.host
    t.hasPort = ref.hasPort
    t.port = ref.port
    t.path = removeDotSegments(ref.path)
    t.hasQuery = ref.hasQuery
    t.query = ref.query
  } else if (ref.hasAuthority) {
    t.hasScheme = true
    t.scheme = base.scheme
    t.hasAuthority = true
    t.hasUserinfo = ref.hasUserinfo
    t.userinfo = ref.userinfo
    t.host = ref.host
    t.hasPort = ref.hasPort
    t.port = ref.port
    t.path = removeDotSegments(ref.path)
    t.hasQuery = ref.hasQuery
    t.query = ref.query
  } else {
    t.hasScheme = true
    t.scheme = base.scheme
    t.hasAuthority = base.hasAuthority
    t.hasUserinfo = base.hasUserinfo
    t.userinfo = base.userinfo
    t.host = base.host
    t.hasPort = base.hasPort
    t.port = base.port

    if (ref.path === '') {
      t.path = base.path
      if (ref.hasQuery) {
        t.hasQuery = true
        t.query = ref.query
      } else {
        t.hasQuery = base.hasQuery
        t.query = base.query
      }
    } else {
      if (ref.path.startsWith('/')) {
        t.path = removeDotSegments(ref.path)
      } else {
        t.path = removeDotSegments(mergePaths(base, ref.path))
      }
      t.hasQuery = ref.hasQuery
      t.query = ref.query
    }
  }

  t.hasFragment = ref.hasFragment
  t.fragment = ref.fragment

  return t
}
"}

