      if (isUnreserved(ch)) out += ch
      else out += '%' + upper
      i += 2
    } else {
      out += c
    }
  }
  return out
}

function asciiLowerCase(s) {
  let out = ''
  for (const c of s) {
    const code = c.codePointAt(0)
    if (code >= 65 && code <= 90) out += String.fromCharCode(code + 32)
    else out += c
  }
  return out
}

/** Remove dot segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '/..') {
      input = '/'
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const match = /^\/?[^/]*/.exec(input)[0]
      input = input.slice(match.length)
      output += match
    }
  }
  return output
}

/** Normalize a parsed URI reference. Throws UriError on invalid percent-encodings. */
export function normalize(t) {
  const r = { ...t }
  if (r.hasScheme) r.scheme = asciiLowerCase(r.scheme)

  r.path = percentNormalize(r.path, 'path')
  if (r.hasUserinfo) r.userinfo = percentNormalize(r.userinfo, 'userinfo')
  if (r.hasAuthority) r.host = percentNormalize(r.host, 'host')
  if (r.hasQuery) r.query = percentNormalize(r.query, 'query')
  if (r.hasFragment) r.fragment = percentNormalize(r.fragment, 'fragment')

  if (r.hasAuthority) r.host = asciiLowerCase(r.host)

  if (r.hasPort) {
    const def = r.hasScheme ? DEFAULT_PORTS[r.scheme] : undefined
    if (r.port === '' || (def !== undefined && r.port === def)) {
      r.hasPort = false
      r.port = ''
    }
  }

  r.path = removeDotSegments(r.path)

  if (r.hasAuthority && r.path === '') r.path = '/'

  return r
}

function mergePaths(base, refPath) {
  if (base.hasAuthority && base.path === '') return '/' + refPath
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/** Resolve a reference against a base per RFC 3986 section 5.2.2, strict form. */
export function resolveRef(base, ref) {
  const t = {}

  if (ref.hasScheme) {
    t.hasScheme = true
    t.scheme = ref.scheme
    t.hasAuthority = ref.hasAuthority
    t.hasUserinfo = ref.hasUserinfo
    t.userinfo = ref.userinfo
    t.host = ref.host
    t.hasPort = ref.hasPort
    t.port = ref.port
    t.path = removeDotSegments(ref.path)
    t.hasQuery = ref.hasQuery
    t.query = ref.query
  } else if (ref.hasAuthority) {
    t.hasScheme = true
    t.scheme = base.scheme
    t.hasAuthority = true
    t.hasUserinfo = ref.hasUserinfo
    t.userinfo = ref.userinfo
    t.host = ref.host
    t.hasPort = ref.hasPort
    t.port = ref.port
    t.path = removeDotSegments(ref.path)
    t.hasQuery = ref.hasQuery
    t.query = ref.query
  } else {
    t.hasScheme = true
    t.scheme = base.scheme
    t.hasAuthority = base.hasAuthority
    t.hasUserinfo = base.hasUserinfo
    t.userinfo = base.userinfo
    t.host = base.host
    t.hasPort = base.hasPort
    t.port = base.port

    if (ref.path === '') {
      t.path = base.path
      if (ref.hasQuery) {
        t.hasQuery = true
        t.query = ref.query
      } else {
        t.hasQuery = base.hasQuery
        t.query = base.query
      }
    } else {
      if (ref.path.startsWith('/')) {
        t.path = removeDotSegments(ref.path)
      } else {
        t.path = removeDotSegments(mergePaths(base, ref.path))
      }
      t.hasQuery = ref.hasQuery
      t.query = ref.query
    }
  }

  t.hasFragment = ref.hasFragment
  t.fragment = ref.fragment

  return t
}
"}

