{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseUriRef, normalize, resolveRef, serialize, UriError } from './uri.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const input = readStdin()
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const results = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    try {
      let target
      if (mode === 'normalize') {
        target = parseUriRef(line)
      } else {
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) {
          throw new UriError('expected a base and a reference')
        }
        const baseStr = line.slice(0, spaceIdx)
        const refStr = line.slice(spaceIdx + 1)
        const base = parseUriRef(baseStr)
        if (!base.hasScheme) {
          throw new UriError('the base has no scheme')
        }
        const ref = parseUriRef(refStr)
        target = resolveRef(base, ref)
      }
      const normalized = normalize(target)
      results.push(serialize(normalized))
    } catch (err) {
      if (err instanceof UriError) {
        process.stderr.write(`error: line ${lineNo}: ${err.message}\n`)
        process.exit(2)
      }
      throw err
    }
  }

  let out = ''
  for (const r of results) out += r + '\n'
  process.stdout.write(out)
  process.exit(0)
}

main()
"}

