 * Error used for anything wrong with the election input. `line` is the
 * 1-based line number the problem was found on, or `undefined` when the
 * problem isn't tied to one particular line (the "no candidates" case).
 */
export class InputError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}
"}

