/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection } from './parser.js'
import { runElection } from './election.js'
import { InputError } from './errors.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    fail('usage: cli.js rounds|tally')
  }
  const mode = args[0]

  const input = readStdinSync()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof InputError) {
      if (err.line === undefined) {
        fail(err.message)
      } else {
        fail(`line ${err.line}: ${err.message}`)
      }
    }
    throw err
  }

  const { rounds, winner } = runElection(election)

  let out = ''

  if (mode === 'rounds') {
    rounds.forEach((round, i) => {
      const roundNo = i + 1
      const entries = Object.entries(round.counts).sort((a, b) => {
        if (b[1] !== a[1]) return b[1] - a[1]
        return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
      })
      const parts = entries.map(([name, votes]) => `${name}=${votes}`)
      parts.push(`exhausted=${round.exhausted}`)
      out += `round ${roundNo}: ${parts.join(' ')}\n`
      if (round.eliminated !== null) {
        out += `eliminated ${round.eliminated}\n`
      }
    })
  } else {
    out += `rounds ${rounds.length}\n`
  }

  out += winner !== null ? `winner ${winner}\n` : 'no winner\n'

  process.stdout.write(out)
  process.exit(0)
}

function readStdinSync() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

main()
"}

