 * Parsing of the election text format into a structured election.
 */

export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/**
 * Parse the raw stdin text into { candidates, ballots }.
 * candidates: array of names in declared order.
 * ballots: array of { count: bigint, names: string[] }.
 */
export function parseElection(text) {
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidatesDeclared = false
  let candidateOrder = []
  let candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const first = tokens[0]

    if (first === 'candidates') {
      if (candidatesDeclared) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 2) {
        throw new ParseError(lineNo, 'expected candidates <name>...')
      }
      const seen = new Set()
      for (let j = 1; j < tokens.length; j++) {
        const name = tokens[j]
        if (!NAME_RE.test(name)) {
          throw new ParseError(lineNo, `invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(lineNo, `candidate ${name} is declared twice`)
        }
        seen.add(name)
      }
      candidateOrder = tokens.slice(1)
      candidateSet = seen
      candidatesDeclared = true
    } else if (first === 'ballot') {
      if (!candidatesDeclared) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        throw new ParseError(lineNo, 'expected ballot <count> <candidate>...')
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr)) {
        throw new ParseError(lineNo, 'count must be a positive integer')
      }
      const count = BigInt(countStr)
      const names = tokens.slice(2)
      const seenNames = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(lineNo, `unknown candidate ${name}`)
        }
        if (seenNames.has(name)) {
          throw new ParseError(lineNo, `candidate ${name} is repeated`)
        }
        seenNames.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ParseError(lineNo, `unknown directive ${first}`)
    }
  }

  if (!candidatesDeclared) {
    throw new ParseError(null, 'no candidates')
  }

  return { candidates: candidateOrder, ballots }
}
"}

