 */

/**
 * Run the count.
 * election: { candidates: string[], ballots: { count: bigint, names: string[] }[] }
 * Returns { rounds, winner } where rounds is an array of
 * { votes: Map<string, bigint>, exhausted: bigint, eliminated: string|null }
 * ordered by round, and winner is a candidate name or null.
 */
export function countElection(election) {
  const { candidates, ballots } = election
  const continuing = new Set(candidates)
  const roundsHistory = []
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const c of continuing) votes.set(c, 0n)
    let exhausted = 0n

    for (const ballot of ballots) {
      const chosen = ballot.names.find((n) => continuing.has(n))
      if (chosen !== undefined) {
        votes.set(chosen, votes.get(chosen) + ballot.count)
      } else {
        exhausted += ballot.count
      }
    }

    let active = 0n
    for (const v of votes.values()) active += v

    roundsHistory.push(votes)

    if (active === 0n) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = null
      break
    }

    let roundWinner = null
    for (const c of continuing) {
      if (votes.get(c) * 2n > active) {
        roundWinner = c
        break
      }
    }

    if (roundWinner !== null) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    let minVotes = null
    for (const c of continuing) {
      const v = votes.get(c)
      if (minVotes === null || v < minVotes) minVotes = v
    }
    const tied = [...continuing].filter((c) => votes.get(c) === minVotes)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, roundsHistory)
    continuing.delete(eliminated)
    rounds.push({ votes, exhausted, eliminated })
  }

  return { rounds, winner }
}

function breakTie(tied, roundsHistory) {
  let candidates = tied.slice()
  for (const roundVotes of roundsHistory) {
    if (candidates.length === 1) break
    let min = null
    for (const c of candidates) {
      const v = roundVotes.get(c)
      if (min === null || v < min) min = v
    }
    candidates = candidates.filter((c) => roundVotes.get(c) === min)
  }
  if (candidates.length === 1) return candidates[0]
  return candidates.slice().sort().pop()
}
