import { tokenize, GrammarError } from './lexer.js'

const COMPARE_TYPES = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])
const COMPARE_OP = { EQ: '=', NE: '<>', LT: '<', LE: '<=', GT: '>', GE: '>=' }

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  advance() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.peek()
    if (!t || t.type !== type) throw new GrammarError(`expected ${type}`)
    return this.advance()
  }

  parseFormula() {
    if (this.tokens.length === 0) throw new GrammarError('empty formula')
    const ast = this.parseComparison()
    if (this.pos !== this.tokens.length) throw new GrammarError('trailing tokens')
    return ast
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && COMPARE_TYPES.has(this.peek().type)) {
      const op = COMPARE_OP[this.advance().type]
      const right = this.parseAdditive()
      left = { type: 'compare', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek() && (this.peek().type === 'PLUS' || this.peek().type === 'MINUS')) {
      const op = this.advance().type === 'PLUS' ? '+' : '-'
      const right = this.parseMultiplicative()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek() && (this.peek().type === 'STAR' || this.peek().type === 'SLASH')) {
      const op = this.advance().type === 'STAR' ? '*' : '/'
      const right = this.parsePower()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek() && this.peek().type === 'CARET') {
      this.advance()
      const right = this.parsePower()
      return { type: 'binary', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek() && (this.peek().type === 'PLUS' || this.peek().type === 'MINUS')) {
      const op = this.advance().type === 'PLUS' ? '+' : '-'
      const arg = this.parseUnary()
      return { type: 'unary', op, arg }
    }
    return this.parsePrimary()
  }

