import { parseAddressWord } from './address.js'
import { parseFormula, GrammarError } from './parser.js'
import { numberValue, textValue, ERROR_TOKENS, errorValue } from './values.js'

export class SheetError extends Error {
  constructor(lineNumber, message) {
    super(message)
    this.lineNumber = lineNumber
  }
}

const NUMBER_RE = /^-?\d+(\.\d+)?$/

function parseLiteral(content) {
  if (content === '') return numberValue(0)
  if (ERROR_TOKENS.has(content)) return errorValue(content)
  if (NUMBER_RE.test(content)) return numberValue(parseFloat(content))
  return textValue(content)
}

/**
 * Parse sheet text into a Map from canonical address key to a cell record:
 *  { isFormula, literal (Value, if not formula), ast (AST or null if formula
 *    grammar failed), status, value } — status/value are used by the evaluator.
 * Throws SheetError on invalid addresses or duplicate declarations.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const rawLine = lines[i]
    const stripped = rawLine.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    let sepIndex = -1
    for (let j = 0; j < stripped.length; j++) {
      if (stripped[j] === ' ' || stripped[j] === '\t') {
        sepIndex = j
        break
      }
    }

    let addressText
    let content
    if (sepIndex === -1) {
      addressText = stripped
      content = ''
    } else {
      addressText = stripped.slice(0, sepIndex)
      let k = sepIndex
      while (k < stripped.length && (stripped[k] === ' ' || stripped[k] === '\t')) k++
      content = stripped.slice(k)
    }

    const parsed = parseAddressWord(addressText)
    if (!parsed) {
      throw new SheetError(lineNumber, `invalid cell address ${addressText}`)
    }
    if (cells.has(parsed.key)) {
      throw new SheetError(lineNumber, `cell ${addressText} is declared twice`)
    }

    let record
    if (content.startsWith('=')) {
      let ast = null
      try {
        ast = parseFormula(content.slice(1))
      } catch (e) {
        if (!(e instanceof GrammarError)) throw e
        ast = null
      }
      record = { isFormula: true, ast, status: 'unvisited', value: null }
    } else {
      const literal = parseLiteral(content)
      record = { isFormula: false, ast: null, literal, status: 'done', value: literal }
    }

    cells.set(parsed.key, record)
  }

  return cells
}
