const DEFAULT_PORTS = { http: '80', https: '443', ws: '80', wss: '443', ftp: '21' }

/**
 * Split a URI reference into its generic components. Absent components are
 * `undefined`; present-but-empty components are `''`.
 */
export function parseReference(s) {
  let rest = s
  let scheme

  const stopIdx = rest.search(/[/?#:]/)
  if (stopIdx !== -1 && rest[stopIdx] === ':') {
    scheme = rest.slice(0, stopIdx)
    rest = rest.slice(stopIdx + 1)
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    const endIdx = rest.search(/[/?#]/)
    if (endIdx === -1) {
      authority = rest
      rest = ''
    } else {
      authority = rest.slice(0, endIdx)
      rest = rest.slice(endIdx)
    }
