  constructor(reason, lineNo) {
    super(reason)
    this.reason = reason
    this.lineNo = lineNo
  }
}

export function err(reason, lineNo) {
  return new ParseError(reason, lineNo)
}

const NAME_CHAR = /[A-Za-z0-9_-]/

export function skipWs(line, i) {
  while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
  return i
}

// Skip whitespace, then treat a bare `#`/`;` as the start of a trailing
// comment: the rest of the line is consumed and reported as end-of-line.
export function skipWsComment(line, i) {
  i = skipWs(line, i)
  if (i < line.length && (line[i] === '#' || line[i] === ';')) return line.length
  return i
}

export function parseBasicString(line, i, lineNo) {
  // assumes line[i] === '"'
  i++
  let out = ''
  while (true) {
    if (i >= line.length) throw err('unterminated string', lineNo)
    const c = line[i]
    if (c === '"') return { value: out, i: i + 1 }
    if (c === '\\') {
      i++
