{"file_path":"src/document.js","content":"/**
 * Splits a configuration document into directive lines and interprets
 * each one, building the document tree defined in tree.js.
 */

import { err, skipWs, skipWsComment, parseDottedName } from './lex.js'
import { newRoot, assignDotted, resolveHeaderTable } from './tree.js'
import { parseValue } from './value.js'

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newRoot()
  let currentTable = root
  let currentPath = []

  for (let li = 0; li < lines.length; li++) {
    const lineNo = li + 1
    const line = lines[li]

    const i0 = skipWs(line, 0)
    if (i0 >= line.length) continue // blank line
    if (line[i0] === '#' || line[i0] === ';') continue // comment-only line

    if (line[i0] === '[') {
      let isArray = false
      let j = i0 + 1
      if (j < line.length && line[j] === '[') {
        isArray = true
        j++
      }
      j = skipWsComment(line, j)
      const nameRes = parseDottedName(line, j, lineNo)
      j = skipWsComment(line, nameRes.i)
      if (isArray) {
        if (line[j] === ']' && line[j + 1] === ']') j += 2
        else throw err('unterminated table header', lineNo)
      } else {
        if (line[j] === ']') j += 1
        else throw err('unterminated table header', lineNo)
      }
      j = skipWsComment(line, j)
      if (j < line.length) throw err('trailing text after a table header', lineNo)

      const res = resolveHeaderTable(root, nameRes.parts, isArray, lineNo)
      currentTable = res.table
      currentPath = res.path
    } else {
      const nameRes = parseDottedName(line, i0, lineNo)
      let j = skipWsComment(line, nameRes.i)
      if (j >= line.length || line[j] !== '=') throw err('expected key = value', lineNo)
      j = skipWsComment(line, j + 1)

      const keyAbsPath = currentPath.concat(nameRes.parts)
      const valRes = parseValue(line, j, lineNo, keyAbsPath)
      j = skipWsComment(line, valRes.i)
      if (j < line.length) throw err('trailing text after a value', lineNo)

      assignDotted(currentTable, nameRes.parts, valRes.node, currentPath, lineNo)
    }
  }

  return root
}
"}

