{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-i3dFde/src/lexer.js","content":"import { ConfigError } from './errors.js'

const NAME_CHAR = /[A-Za-z0-9_-]/

export function skipWS(line, pos) {
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) pos++
  return pos
}

function isDelimiter(ch) {
  return ch === undefined || ch === ',' || ch === ']' || ch === '}' || ch === '#' || ch === ';'
}

export function parseBasicString(line, pos, lineNo) {
  // line[pos] === '"'
  pos++
  let out = ''
  while (true) {
    if (pos >= line.length) throw new ConfigError(lineNo, 'unterminated string')
    const ch = line[pos]
    if (ch === '"') {
      pos++
      return { value: out, pos }
    }
    if (ch === '\\') {
      pos++
      if (pos >= line.length) throw new ConfigError(lineNo, 'unterminated string')
      const esc = line[pos]
      switch (esc) {
        case '"':
          out += '"'
          pos++
          break
        case '\\':
          out += '\\'
          pos++
          break
        case 'n':
          out += '\n'
          pos++
          break
        case 't':
          out += '\t'
          pos++
          break
        case 'r':
          out += '\r'
          pos++
          break
        case '0':
          out += '\0'
          pos++
          break
        case 'u': {
          const hex = line.slice(pos + 1, pos + 5)
          if (hex.length < 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) {
            throw new ConfigError(lineNo, 'invalid escape \\u')
          }
          out += String.fromCharCode(parseInt(hex, 16))
          pos += 5
          break
        }
        default:
          throw new ConfigError(lineNo, `invalid escape \\${esc}`)
      }
      continue
    }
    out += ch
    pos++
  }
}

export function parseLiteralString(line, pos, lineNo) {
  // line[pos] === "'"
  pos++
  const start = pos
  while (true) {
    if (pos >= line.length) throw new ConfigError(lineNo, 'unterminated string')
    if (line[pos] === "'") {
      const value = line.slice(start, pos)
      return { value, pos: pos + 1 }
    }
    pos++
  }
}

// Parses a dotted name starting at pos (may have leading whitespace already
// skipped by caller or not - this function skips it itself).
export function parseDottedName(line, pos, lineNo) {
  const segments = []
  while (true) {
    pos = skipWS(line, pos)
    const ch = line[pos]
    if (ch === '"') {
      const r = parseBasicString(line, pos, lineNo)
      segments.push(r.value)
      pos = r.pos
    } else if (ch === "'") {
      const r = parseLiteralString(line, pos, lineNo)
      segments.push(r.value)
      pos = r.pos
    } else if (ch !== undefined && NAME_CHAR.test(ch)) {
      const start = pos
      while (pos < line.length && NAME_CHAR.test(line[pos])) pos++
      segments.push(line.slice(start, pos))
    } else {
      throw new ConfigError(lineNo, 'expected a name')
    }
    pos = skipWS(line, pos)
    if (line[pos] === '.') {
      pos++
      continue
    }
    break
  }
  return { segments, pos }
}

const INT_RE = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*([eE][+-]?[0-9]+(_[0-9]+)*)?|[eE][+-]?[0-9]+(_[0-9]+)*)$/

function normalizeInteger(token) {
  let s = token.replace(/_/g, '')
  let sign = ''
  if (s[0] === '+' || s[0] === '-') {
    if (s[0] === '-') sign = '-'
    s = s.slice(1)
  }
  s = s.replace(/^0+(?=\d)/, '')
  if (/^0+$/.test(s)) return '0'
  return sign + s
}

function normalizeFloatNumber(token) {
  const s = token.replace(/_/g, '')
  return Number(s)
}

// Parses a value starting at pos. Returns { node, pos }.
export function parseValue(line, pos, lineNo) {
  pos = skipWS(line, pos)
  const ch = line[pos]
  if (isDelimiter(ch)) {
    throw new ConfigError(lineNo, 'expected a value')
  }
  if (ch === '"') {
    const r = parseBasicString(line, pos, lineNo)
    return { node: { kind: 'string', value: r.value }, pos: r.pos }
  }
  if (ch === "'") {
    const r = parseLiteralString(line, pos, lineNo)
    return { node: { kind: 'string', value: r.value }, pos: r.pos }
  }
  if (ch === '[') {
    return parseArrayValue(line, pos, lineNo)
  }
  if (ch === '{') {
    return parseInlineTable(line, pos, lineNo)
  }
  // bareword scan
  const start = pos
  while (pos < line.length) {
    const c = line[pos]
    if (c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}') break
    pos++
  }
  const token = line.slice(start, pos)
  if (token === 'true') return { node: { kind: 'boolean', value: true }, pos }
  if (token === 'false') return { node: { kind: 'boolean', value: false }, pos }
  if (INT_RE.test(token)) {
    return { node: { kind: 'integer', text: normalizeInteger(token) }, pos }
  }
  if (FLOAT_RE.test(token)) {
    return { node: { kind: 'float', value: normalizeFloatNumber(token) }, pos }
  }
  throw new ConfigError(lineNo, `invalid value ${token}`)
}

function parseArrayValue(line, pos, lineNo) {
  // line[pos] === '['
  pos++
  const items = []
  pos = skipWS(line, pos)
  if (line[pos] === ']') {
    return { node: { kind: 'array', items }, pos: pos + 1 }
  }
  while (true) {
    pos = skipWS(line, pos)
    if (pos >= line.length) throw new ConfigError(lineNo, 'unterminated array')
    if (line[pos] === '#' || line[pos] === ';') throw new ConfigError(lineNo, 'unterminated array')
    const r = parseValue(line, pos, lineNo)
    items.push(r.node)
    pos = skipWS(line, r.pos)
    if (pos >= line.length) throw new ConfigError(lineNo, 'unterminated array')
    const c = line[pos]
    if (c === '#' || c === ';') throw new ConfigError(lineNo, 'unterminated array')
    if (c === ',') {
      pos++
      pos = skipWS(line, pos)
      if (line[pos] === ']') {
        return { node: { kind: 'array', items }, pos: pos + 1 }
      }
      continue
    }
    if (c === ']') {
      return { node: { kind: 'array', items }, pos: pos + 1 }
    }
    throw new ConfigError(lineNo, 'unterminated array')
  }
}

function assignInto(tableNode, segments, valueNode, lineNo) {
  let node = tableNode
  const pathParts = []
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    pathParts.push(seg)
    node = stepThrough(node, seg, pathParts.join('.'), lineNo)
  }
  const lastSeg = segments[segments.length - 1]
  pathParts.push(lastSeg)
  if (node.map.has(lastSeg)) {
    throw new ConfigError(lineNo, `key ${pathParts.join('.')} is defined twice`)
  }
