  for (let i = 0; i < len; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}

function sortedKeys(map) {
  return Array.from(map.keys()).sort(codePointCompare)
}

function typeName(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'array':
    case 'arrayOfTables':
      return 'array'
    default:
      return node.kind
  }
}

function serializeNode(node, depth) {
  const pad = '  '.repeat(depth)
  const padChild = '  '.repeat(depth + 1)
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node.map)
      if (keys.length === 0) return '{}'
      const parts = keys.map(
        (k) => `${padChild}${JSON.stringify(k)}: ${serializeNode(node.map.get(k), depth + 1)}`
      )
      return '{\n' + parts.join(',\n') + '\n' + pad + '}'
    }
    case 'array':
    case 'arrayOfTables': {
      const items = node.kind === 'array' ? node.items : node.items
      if (items.length === 0) return '[]'
      const parts = items.map((it) => padChild + serializeNode(it, depth + 1))
      return '[\n' + parts.join(',\n') + '\n' + pad + ']'
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.text
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJson(root) {
  return serializeNode(root, 0) + '\n'
}

function visitChildren(node, path, out) {
  if (node.kind === 'table') {
    for (const k of sortedKeys(node.map)) {
      const child = node.map.get(k)
      const childPath = path === '' ? k : `${path}.${k}`
      out.push(`${childPath} ${typeName(child)}`)
      visitChildren(child, childPath, out)
    }
  } else if (node.kind === 'array' || node.kind === 'arrayOfTables') {
    node.items.forEach((child, i) => {
      const childPath = `${path}[${i}]`
      out.push(`${childPath} ${typeName(child)}`)
      visitChildren(child, childPath, out)
    })
  }
}

export function toKeys(root) {
  const out = []
  visitChildren(root, '', out)
  return out.map((l) => l + '\n').join('')
}
"}

