{"file_path":"./src/parser.js","content":"import { ParseError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_-]+/
const DIGITS = String.raw`\d+(?:_\d+)*`
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FRAC = String.raw`\.${DIGITS}`
const EXP = String.raw`[eE][+-]?${DIGITS}`
const FLOAT_RE = new RegExp(`^[+-]?${DIGITS}(?:${FRAC}(?:${EXP})?|${EXP})$`)

function newTable(path) {
  return { type: 'table', map: new Map(), headered: false, path }
}

class LineScanner {
  constructor(line, lineNo, fail) {
    this.s = line
    this.n = line.length
    this.i = 0
    this.lineNo = lineNo
    this.fail = fail
  }

  atEnd() {
    return this.i >= this.n
  }

  skipWSAndComment() {
    const { s } = this
    while (this.i < this.n && (s[this.i] === ' ' || s[this.i] === '\t')) this.i++
    if (this.i < this.n && (s[this.i] === '#' || s[this.i] === ';')) this.i = this.n
  }

  parseBasicString() {
    const { s } = this
    this.i++ // consume opening quote
    let out = ''
    for (;;) {
      if (this.i >= this.n) this.fail('unterminated string')
      const c = s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        this.i++
        if (this.i >= this.n) this.fail('unterminated string')
        const e = s[this.i]
        switch (e) {
          case '"':
            out += '"'
            this.i++
            break
          case '\\':
            out += '\\'
            this.i++
            break
          case 'n':
            out += '\n'
            this.i++
            break
          case 't':
            out += '\t'
            this.i++
            break
          case 'r':
            out += '\r'
            this.i++
            break
          case '0':
            out += '\0'
            this.i++
            break
          case 'u': {
            this.i++
            const hex = s.slice(this.i, this.i + 4)
            if (hex.length < 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) this.fail('invalid escape \\u')
            out += String.fromCharCode(parseInt(hex, 16))
            this.i += 4
            break
          }
          default:
            this.fail(`invalid escape \\${e}`)
        }
      } else {
        out += c
        this.i++
      }
    }
  }

  parseLiteralString() {
    const { s } = this
    this.i++ // consume opening quote
    let out = ''
    for (;;) {
      if (this.i >= this.n) this.fail('unterminated string')
      const c = s[this.i]
      if (c === "'") {
        this.i++
        return out
      }
      out += c
      this.i++
    }
  }

  parseName() {
    this.skipWSAndComment()
    if (this.i >= this.n) this.fail('expected a name')
    const c = this.s[this.i]
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    const m = NAME_RE.exec(this.s.slice(this.i))
    if (!m) this.fail('expected a name')
    this.i += m[0].length
    return m[0]
  }

  parseDottedName() {
    const names = [this.parseName()]
    for (;;) {
      const save = this.i
      this.skipWSAndComment()
      if (this.i < this.n && this.s[this.i] === '.') {
        this.i++
        names.push(this.parseName())
      } else {
        this.i = save
        break
      }
    }
    return names
  }

  resolveAssignTarget(tableNode, names) {
    let cur = tableNode
    let curPath = tableNode.path
    for (let idx = 0; idx < names.length - 1; idx++) {
      const name = names[idx]
      const childPath = curPath === '' ? name : `${curPath}.${name}`
      if (cur.map.has(name)) {
        const ex = cur.map.get(name)
        if (ex.type === 'table') {
          cur = ex
        } else if (ex.type === 'atable') {
          cur = ex.items[ex.items.length - 1]
        } else {
          this.fail(`${childPath} is not a table`)
        }
      } else {
        const nt = newTable(childPath)
        cur.map.set(name, nt)
        cur = nt
      }
      curPath = childPath
    }
    const finalName = names[names.length - 1]
    const finalPath = curPath === '' ? finalName : `${curPath}.${finalName}`
    if (cur.map.has(finalName)) this.fail(`key ${finalPath} is defined twice`)
    return { cur, finalName, finalPath }
  }

  readValue(prefixPath) {
    this.skipWSAndComment()
    if (this.i >= this.n) this.fail('expected a value')
    const c = this.s[this.i]
    if (c === '"') return { type: 'string', value: this.parseBasicString() }
    if (c === "'") return { type: 'string', value: this.parseLiteralString() }
    if (c === '[') return this.parseArrayValue(prefixPath)
    if (c === '{') return this.parseInlineTableValue(prefixPath)
    return this.parseUnquotedValue()
  }

  parseUnquotedValue() {
    const { s } = this
    const start = this.i
    while (this.i < this.n && s[this.i] !== ' ' && s[this.i] !== '\t' && s[this.i] !== ',' && s[this.i] !== ']' && s[this.i] !== '}') {
      this.i++
    }
    const token = s.slice(start, this.i)
    if (token === 'true') return { type: 'boolean', value: true }
    if (token === 'false') return { type: 'boolean', value: false }
    if (INT_RE.test(token)) {
      const negative = token[0] === '-'
      const digits = token.replace(/^[+-]/, '').replace(/_/g, '')
      let value = BigInt(digits)
      if (negative) value = -value
      return { type: 'integer', value }
    }
    if (FLOAT_RE.test(token)) {
      return { type: 'float', value: Number(token.replace(/_/g, '')) }
    }
    this.fail(`invalid value ${token}`)
  }

  parseArrayValue(prefixPath) {
    this.i++ // consume '['
    const items = []
    this.skipWSAndComment()
    if (this.i >= this.n) this.fail('unterminated array')
    if (this.s[this.i] === ']') {
      this.i++
      return { type: 'array', items }
    }
    for (;;) {
      items.push(this.readValue(prefixPath))
      this.skipWSAndComment()
      if (this.i >= this.n) this.fail('unterminated array')
      if (this.s[this.i] === ',') {
        this.i++
        this.skipWSAndComment()
        if (this.i >= this.n) this.fail('unterminated array')
        if (this.s[this.i] === ']') {
          this.i++
          break
        }
        continue
      } else if (this.s[this.i] === ']') {
        this.i++
        break
      } else {
        this.fail('unterminated array')
      }
    }
    return { type: 'array', items }
  }

  parseInlineTableValue(prefixPath) {
    this.i++ // consume '{'
    const map = new Map()
    const localNode = { type: 'table', map, headered: false, path: prefixPath }
    this.skipWSAndComment()
    if (this.i >= this.n) this.fail('unterminated inline table')
    if (this.s[this.i] === '}') {
      this.i++
      return { type: 'table', map }
    }
    for (;;) {
      const names = this.parseDottedName()
      this.skipWSAndComment()
      if (this.i >= this.n || this.s[this.i] !== '=') this.fail('expected = in an inline table')
      this.i++
      const { cur, finalName, finalPath } = this.resolveAssignTarget(localNode, names)
      const val = this.readValue(finalPath)
      cur.map.set(finalName, val)
      this.skipWSAndComment()
      if (this.i >= this.n) this.fail('unterminated inline table')
      if (this.s[this.i] === ',') {
        this.i++
        this.skipWSAndComment()
        if (this.i >= this.n) this.fail('unterminated inline table')
        continue
      } else if (this.s[this.i] === '}') {
        this.i++
        break
      } else {
        this.fail('unterminated inline table')
      }
    }
    return { type: 'table', map }
  }
}

export class Parser {
  constructor() {
    this.root = newTable('')
    this.currentTable = this.root
  }

  fail(reason) {
    throw new ParseError(this.lineNo, reason)
  }

  parseDocument(text) {
    let lines = text.split('\n')
    if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
    for (let idx = 0; idx < lines.length; idx++) {
      this.lineNo = idx + 1
      this.processLine(lines[idx])
    }
    return this.root
  }

  processLine(line) {
    let j = 0
    while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
    if (j >= line.length) return
    if (line[j] === '#' || line[j] === ';') return

    const boundFail = (reason) => this.fail(reason)
    const scanner = new LineScanner(line, this.lineNo, boundFail)
    scanner.i = j

    if (scanner.s[scanner.i] === '[') {
      this.parseHeaderLine(scanner)
    } else {
      this.parseKeyValueLine(scanner)
    }
  }

  parseHeaderLine(scanner) {
    scanner.i++ // consume '['
    let isArray = false
    if (scanner.i < scanner.n && scanner.s[scanner.i] === '[') {
      isArray = true
      scanner.i++
    }
    const names = scanner.parseDottedName()
    scanner.skipWSAndComment()
    if (scanner.i >= scanner.n || scanner.s[scanner.i] !== ']') this.fail('unterminated table header')
    scanner.i++
    if (isArray) {
      if (scanner.i >= scanner.n || scanner.s[scanner.i] !== ']') this.fail('unterminated table header')
      scanner.i++
    }
    scanner.skipWSAndComment()
    if (scanner.i < scanner.n) this.fail('trailing text after a table header')
    this.applyHeader(names, isArray)
  }

  applyHeader(names, isArray) {
    let cur = this.root
    let curPath = ''
    for (let idx = 0; idx < names.length - 1; idx++) {
      const name = names[idx]
      const childPath = curPath === '' ? name : `${curPath}.${name}`
      if (cur.map.has(name)) {
        const ex = cur.map.get(name)
        if (ex.type === 'table') {
          cur = ex
        } else if (ex.type === 'atable') {
          cur = ex.items[ex.items.length - 1]
        } else {
          this.fail(`${childPath} is not a table`)
        }
      } else {
        const nt = newTable(childPath)
        cur.map.set(name, nt)
        cur = nt
      }
      curPath = childPath
    }
    const finalName = names[names.length - 1]
    const finalPath = curPath === '' ? finalName : `${curPath}.${finalName}`

    if (!isArray) {
      if (cur.map.has(finalName)) {
        const ex = cur.map.get(finalName)
        if (ex.type !== 'table') this.fail(`${finalPath} is not a table`)
        if (ex.headered) this.fail(`table ${finalPath} is defined twice`)
        ex.headered = true
        this.currentTable = ex
      } else {
        const nt = newTable(finalPath)
        nt.headered = true
        cur.map.set(finalName, nt)
        this.currentTable = nt
      }
    } else {
      if (cur.map.has(finalName)) {
        const ex = cur.map.get(finalName)
        if (ex.type !== 'atable') this.fail(`${finalPath} is not an array of tables`)
        const nt = newTable(finalPath)
        ex.items.push(nt)
        this.currentTable = nt
      } else {
        const nt = newTable(finalPath)
        const at = { type: 'atable', items: [nt] }
        cur.map.set(finalName, at)
        this.currentTable = nt
      }
    }
  }

  parseKeyValueLine(scanner) {
    const names = scanner.parseDottedName()
    scanner.skipWSAndComment()
    if (scanner.i >= scanner.n || scanner.s[scanner.i] !== '=') this.fail('expected key = value')
    scanner.i++
    const { cur, finalName, finalPath } = scanner.resolveAssignTarget(this.currentTable, names)
    const val = scanner.readValue(finalPath)
    scanner.skipWSAndComment()
    if (scanner.i < scanner.n) this.fail('trailing text after a value')
    cur.map.set(finalName, val)
  }
}

export function parseDocument(text) {
  return new Parser().parseDocument(text)
}
"}

