{"file_path":"./src/format.js","content":"function codePointCompare(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const len = Math.min(ai.length, bi.length)
  for (let k = 0; k < len; k++) {
    const ca = ai[k].codePointAt(0)
    const cb = bi[k].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}

function sortedKeys(map) {
  return [...map.keys()].sort(codePointCompare)
}

function indent(level) {
  return '  '.repeat(level)
}

function jsonValueToText(node, level) {
  switch (node.type) {
    case 'table': {
      const keys = sortedKeys(node.map)
      if (keys.length === 0) return '{}'
      const inner = keys
        .map((k) => `${indent(level + 1)}${JSON.stringify(k)}: ${jsonValueToText(node.map.get(k), level + 1)}`)
        .join(',\n')
      return `{\n${inner}\n${indent(level)}}`
    }
    case 'atable': {
      if (node.items.length === 0) return '[]'
      const inner = node.items.map((it) => `${indent(level + 1)}${jsonValueToText(it, level + 1)}`).join(',\n')
      return `[\n${inner}\n${indent(level)}]`
    }
    case 'array': {
      if (node.items.length === 0) return '[]'
      const inner = node.items.map((it) => `${indent(level + 1)}${jsonValueToText(it, level + 1)}`).join(',\n')
      return `[\n${inner}\n${indent(level)}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

export function toJSONDocument(root) {
  return `${jsonValueToText(root, 0)}\n`
}

function typeName(node) {
  switch (node.type) {
    case 'table':
      return 'table'
    case 'atable':
      return 'array'
    case 'array':
      return 'array'
    case 'string':
      return 'string'
    case 'integer':
      return 'integer'
    case 'float':
      return 'float'
    case 'boolean':
      return 'boolean'
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

function walkKeys(node, pathStr, out) {
  if (node.type === 'table') {
    const keys = sortedKeys(node.map)
    for (const k of keys) {
      const child = node.map.get(k)
      const childPath = pathStr === '' ? k : `${pathStr}.${k}`
      out.push(`${childPath} ${typeName(child)}`)
      walkKeys(child, childPath, out)
    }
  } else if (node.type === 'atable' || node.type === 'array') {
    node.items.forEach((it, idx) => {
      const childPath = `${pathStr}[${idx}]`
      out.push(`${childPath} ${typeName(it)}`)
      walkKeys(it, childPath, out)
    })
  }
}

export function toKeysDocument(root) {
  const out = []
  walkKeys(root, '', out)
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}
"}

