/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseGraph, GraphError } from './parse.js'
import { findCycle, computeSchedule, packSchedule } from './graph.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

async function main() {
  const args = process.argv.slice(2)

  let mode
  let workers

  if (args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) {
    mode = args[0]
  } else if (args.length === 2 && args[0] === 'pack') {
    mode = 'pack'
    const workersStr = args[1]
    if (!/^[1-9][0-9]*$/.test(workersStr)) {
      process.stderr.write('error: workers must be a positive integer\n')
      process.exit(2)
    }
    workers = parseInt(workersStr, 10)
  } else {
    process.stderr.write(USAGE + '\n')
    process.exit(2)
  }

  const input = await readAllStdin()

  let tasks
  let deps
  try {
    ;({ tasks, deps } = parseGraph(input))
  } catch (err) {
    if (err instanceof GraphError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const cycle = findCycle(tasks, deps)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exit(3)
  }

  if (mode === 'waves') {
    const schedule = computeSchedule(tasks, deps)
    let maxDepth = -1
    let total = 0
    for (const { depth, finish } of schedule.values()) {
      if (depth > maxDepth) maxDepth = depth
      if (finish > total) total = finish
    }
    const lines = []
    for (let d = 0; d <= maxDepth; d++) {
      const names = []
      for (const [name, info] of schedule.entries()) {
        if (info.depth === d) names.push(name)
      }
      names.sort()
      lines.push(`wave ${d}: ${names.join(' ')}`)
    }
    lines.push(`total ${total}`)
    process.stdout.write(lines.join('\n') + '\n')
  } else if (mode === 'explain') {
    const schedule = computeSchedule(tasks, deps)
    let total = 0
    for (const { finish } of schedule.values()) {
      if (finish > total) total = finish
    }
    const names = [...tasks.keys()].sort()
    const lines = []
    for (const name of names) {
      const { start, finish, depth } = schedule.get(name)
      lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
    }
    lines.push(`total ${total}`)
    process.stdout.write(lines.join('\n') + '\n')
  } else if (mode === 'pack') {
    const { runs, makespan } = packSchedule(tasks, deps, workers)
    const lines = []
    for (let w = 0; w < workers; w++) {
      const parts = runs[w].map((r) => ` ${r.name}@${r.start}-${r.finish}`)
      lines.push(`worker ${w}:${parts.join('')}`)
    }
    lines.push(`makespan ${makespan}`)
    process.stdout.write(lines.join('\n') + '\n')
  }
}

function readAllStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

main().catch((err) => {
  process.stderr.write(String(err && err.stack ? err.stack : err) + '\n')
  process.exit(1)
})
"}

