function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

// Reconstruct the lines one side contributes to a region: the base lines
// before its first change in the region, its changes' lines (with the base
// lines between consecutive changes of the same side left untouched), and
// the base lines after its last change in the region.
function sideLinesForRegion(base, region, sideChanges) {
  const result = []
  let pos = region.start
  for (const change of sideChanges) {
    for (let k = pos; k < change.start; k++) result.push(base[k])
    for (const line of change.lines) result.push(line)
    pos = change.end
  }
  for (let k = pos; k < region.end; k++) result.push(base[k])
  return result
}

/**
 * Group the changes from both sides into regions, and resolve each region.
 * Returns an array of entries, in base order:
 *   { kind: 'stable', lines }
 *   { kind: 'mine' | 'theirs' | 'both', lines }
 *   { kind: 'conflict', mine, base, theirs }
 */
export function computeRegions(mine, base, theirs) {
  const mineChanges = changesAgainstBase(mine, base).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = changesAgainstBase(theirs, base).map(c => ({ ...c, side: 'theirs' }))

  const allChanges = mineChanges
    .concat(theirsChanges)
    .sort((a, b) => {
      if (a.start !== b.start) return a.start - b.start
      if (a.side === b.side) return 0
      return a.side === 'mine' ? -1 : 1
    })

  const grouped = []
  for (const change of allChanges) {
    const last = grouped[grouped.length - 1]
    if (last && change.start <= last.end) {
      last.end = Math.max(last.end, change.end)
      last.changes.push(change)
    } else {
      grouped.push({ start: change.start, end: change.end, changes: [change] })
    }
  }

  const entries = []
  let pos = 0
  for (const region of grouped) {
    if (region.start > pos) {
      entries.push({ kind: 'stable', lines: base.slice(pos, region.start) })
    }
    entries.push(resolveRegion(base, region))
    pos = region.end
  }
  if (base.length > pos) {
    entries.push({ kind: 'stable', lines: base.slice(pos, base.length) })
  }
  return entries
}

function resolveRegion(base, region) {
  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')
  const baseLines = base.slice(region.start, region.end)

  if (mineChanges.length > 0 && theirsChanges.length === 0) {
    return { kind: 'mine', lines: sideLinesForRegion(base, region, mineChanges) }
  }
  if (theirsChanges.length > 0 && mineChanges.length === 0) {
    return { kind: 'theirs', lines: sideLinesForRegion(base, region, theirsChanges) }
  }

  const mineLines = sideLinesForRegion(base, region, mineChanges)
  const theirsLines = sideLinesForRegion(base, region, theirsChanges)

  if (linesEqual(mineLines, theirsLines)) {
    return { kind: 'both', lines: mineLines }
  }
  if (linesEqual(mineLines, baseLines)) {
    return { kind: 'theirs', lines: theirsLines }
  }
  if (linesEqual(theirsLines, baseLines)) {
    return { kind: 'mine', lines: mineLines }
  }
  return { kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines }
}
