 * Split raw standard input into the three documents it holds: mine, base,
 * and theirs. Throws with a message describing the problem when the input
 * does not hold exactly three parts.
 */
export function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }

  if (parts.length !== 3) {
    throw new Error('expected three parts separated by %%%')
  }
  return parts
}
"}

