/**
 * Render the resolved regions as a merge (or merge2, when `withBase` is
 * false) result. Returns the output text and whether a conflict occurred.
 */
export function formatMerge(entries, withBase) {
  const lines = []
  let conflict = false
  for (const entry of entries) {
    if (entry.kind === 'conflict') {
      conflict = true
      lines.push('<<<<<<< mine')
      lines.push(...entry.mine)
      if (withBase) {
        lines.push('||||||| base')
        lines.push(...entry.base)
      }
      lines.push('=======')
      lines.push(...entry.theirs)
      lines.push('>>>>>>> theirs')
    } else {
      lines.push(...entry.lines)
    }
  }
  return { text: linesToText(lines), conflict }
}

/**
 * Render the resolved regions as the `regions` report. Returns the output
 * text and whether a conflict occurred.
 */
export function formatRegions(entries) {
  const lines = []
  let conflict = false
  for (const entry of entries) {
    if (entry.kind === 'conflict') {
      conflict = true
      lines.push(`conflict mine=${entry.mine.length} base=${entry.base.length} theirs=${entry.theirs.length}`)
    } else {
      lines.push(`${entry.kind} ${entry.lines.length}`)
    }
  }
  return { text: linesToText(lines), conflict }
}
"}

