/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { readFileSync } from 'node:fs'
import { parseInput } from './parse.js'
import { computeRegions } from './diff3.js'
import { formatMerge, formatRegions } from './format.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  let mine, base, theirs
  try {
    ;[mine, base, theirs] = parseInput(input)
  } catch (err) {
    fail(err.message)
    return
  }

  const entries = computeRegions(mine, base, theirs)

  let result
  if (mode === 'merge') {
    result = formatMerge(entries, true)
  } else if (mode === 'merge2') {
    result = formatMerge(entries, false)
  } else {
    result = formatRegions(entries)
  }

  process.stdout.write(result.text)
  process.exit(result.conflict ? 1 : 0)
}

main()
"}

