import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

class ParseError extends Error {
  constructor(lineNum, reason) {
    super(`line ${lineNum}: ${reason}`)
    this.lineNum = lineNum
    this.reason = reason
  }
}

function isValidName(str) {
  return NAME_RE.test(str)
}

// Validates that `str` is a well-formed unsigned decimal integer (no sign,
// no leading zero unless the value is exactly zero) of at least `min`.
// Returns the parsed BigInt, or `null` when invalid.
function parseIntField(str, min) {
  if (!INT_RE.test(str)) return null
  const value = BigInt(str)
  if (value < min) return null
  return value
}

function splitLine(line) {
  const trimmed = line.trim()
  if (trimmed === '' || trimmed.startsWith('#')) return null
  return trimmed.split(/\s+/)
}

// Finds the route whose prefix is longest among those that match `key`, or
// `null` if none match.
function findRoute(routes, key) {
  let best = null
  let bestLen = -1
  for (const [prefix, route] of routes) {
    if (key.startsWith(prefix) && prefix.length > bestLen) {
      best = route
      bestLen = prefix.length
    }
  }
  return best
}

// Runs the whole limiter file described by `text` and returns
// `{ events: [{ tick, key, allowed, deniedBy }] }` in log order.
// Throws a ParseError (with a `.lineNum` and `.reason`) on the first
// malformed line.
export function simulate(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const policies = new Map() // name -> policy object
  const routes = new Map() // prefix -> { policyNames: [...], policies: [...] }
  let seenEvent = false
  let lastTick = null
  const events = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNum = i + 1
    const parts = splitLine(rawLines[i])
    if (parts === null) continue

    const word = parts[0]

    if (word === 'bucket') {
      if (seenEvent) throw new ParseError(lineNum, 'declarations must come before the first event')
      if (parts.length !== 5) throw new ParseError(lineNum, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityStr, refillStr, perStr] = parts
      if (!isValidName(name)) throw new ParseError(lineNum, `invalid policy name ${name}`)
      const capacity = parseIntField(capacityStr, 1n)
      if (capacity === null) throw new ParseError(lineNum, 'capacity must be an integer of at least 1')
      const refill = parseIntField(refillStr, 0n)
      if (refill === null) throw new ParseError(lineNum, 'refill must be an integer of at least 0')
      const per = parseIntField(perStr, 1n)
      if (per === null) throw new ParseError(lineNum, 'per must be an integer of at least 1')
      if (policies.has(name)) throw new ParseError(lineNum, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(capacity, refill, per))
      continue
    }

    if (word === 'window') {
      if (seenEvent) throw new ParseError(lineNum, 'declarations must come before the first event')
      if (parts.length !== 4) throw new ParseError(lineNum, 'expected window <name> <limit> <span>')
      const [, name, limitStr, spanStr] = parts
      if (!isValidName(name)) throw new ParseError(lineNum, `invalid policy name ${name}`)
      const limit = parseIntField(limitStr, 0n)
      if (limit === null) throw new ParseError(lineNum, 'limit must be an integer of at least 0')
      const span = parseIntField(spanStr, 1n)
      if (span === null) throw new ParseError(lineNum, 'span must be an integer of at least 1')
      if (policies.has(name)) throw new ParseError(lineNum, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(limit, span))
      continue
    }

    if (word === 'route') {
      if (seenEvent) throw new ParseError(lineNum, 'declarations must come before the first event')
      if (parts.length < 3) throw new ParseError(lineNum, 'expected route <prefix> <policy>...')
      const prefix = parts[1]
      if (!isValidName(prefix)) throw new ParseError(lineNum, `invalid route prefix ${prefix}`)
      const policyNames = parts.slice(2)
      const routePolicies = []
      for (const name of policyNames) {
        const policy = policies.get(name)
        if (policy === undefined) throw new ParseError(lineNum, `unknown policy ${name}`)
        routePolicies.push({ name, policy })
      }
      if (routes.has(prefix)) throw new ParseError(lineNum, `prefix ${prefix} is routed twice`)
      routes.set(prefix, { policies: routePolicies })
      continue
    }

    if (word === 'event') {
      if (parts.length !== 3) throw new ParseError(lineNum, 'expected event <tick> <key>')
      const [, tickStr, key] = parts
      const tick = parseIntField(tickStr, 0n)
      if (tick === null) throw new ParseError(lineNum, 'tick must be an integer of at least 0')
      if (!isValidName(key)) throw new ParseError(lineNum, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(lineNum, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      seenEvent = true

      const route = findRoute(routes, key)
      let allowed = true
      let deniedBy = null

      if (route !== null) {
        for (const { policy } of route.policies) {
          policy.advance(key, tick)
        }
        for (const { name, policy } of route.policies) {
          if (!policy.allow(key)) {
            allowed = false
            deniedBy = name
            break
          }
        }
        if (allowed) {
          for (const { policy } of route.policies) {
            policy.record(key, tick)
          }
        }
      }

      events.push({ tick, key, allowed, deniedBy })
      continue
    }

    throw new ParseError(lineNum, `unknown directive ${word}`)
  }

  return { events }
}
"}

