 * Parse a sheet's raw text into a map of declared cells.
 */

import { parseAddress, addressKey } from './address.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/**
 * Parse sheet text into a Map from canonical address string to
 * { content, col, row, line }. Throws SheetError on an invalid address or a
 * duplicate declaration.
 */
export function parseSheet(text) {
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const stripped = lines[i].replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const m = /^([^ \t]+)/.exec(stripped)
    const addrToken = m[1]
    const rest = stripped.slice(addrToken.length).replace(/^[ \t]+/, '')

    const addr = parseAddress(addrToken)
    if (!addr) {
      throw new SheetError(lineNo, `invalid cell address ${addrToken}`)
    }
    const key = addressKey(addr.col, addr.row)
    if (cells.has(key)) {
      throw new SheetError(lineNo, `cell ${key} is declared twice`)
    }
    cells.set(key, { content: rest, col: addr.col, row: addr.row, line: lineNo })
  }

  return cells
}
"}

