 * Evaluate every declared cell's value, with memoization and cycle
 * detection.
 */

import { parseFormula, FUNCTION_NAMES } from './parser.js'
import { addressKey } from './address.js'
import {
  NUMBER,
  ERROR,
  parseLiteral,
  toNumberForArithmetic,
  toBoolean,
  compareValues,
} from './values.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

function getCellInfo(cells, addr, parseCache) {
  if (parseCache.has(addr)) return parseCache.get(addr)
  const cell = cells.get(addr)
  let info
  if (!cell) {
    info = { kind: 'literal', value: NUMBER(0) }
  } else if (cell.content.startsWith('=')) {
    const parsed = parseFormula(cell.content.slice(1))
    if (!parsed.ok) info = { kind: 'formulaError' }
    else info = { kind: 'formula', ast: parsed.ast }
  } else {
    info = { kind: 'literal', value: parseLiteral(cell.content) }
  }
  parseCache.set(addr, info)
  return info
}

function expandRange(node) {
  if (!node.from || !node.to) return null
  const colMin = Math.min(node.from.col, node.to.col)
  const colMax = Math.max(node.from.col, node.to.col)
  const rowMin = Math.min(node.from.row, node.to.row)
  const rowMax = Math.max(node.from.row, node.to.row)
  const out = []
  for (let c = colMin; c <= colMax; c++) {
    for (let r = rowMin; r <= rowMax; r++) {
      out.push(addressKey(c, r))
    }
  }
  return out
}

function finiteOrDivZero(x) {
  if (!Number.isFinite(x)) return ERROR('#DIV/0!')
  return NUMBER(x)
}

export function evaluateSheet(cells) {
  const parseCache = new Map()
  const state = new Map() // addr -> 'inprogress' | 'done'
  const cache = new Map() // addr -> value

  function evaluateCell(addr, stack) {
    if (state.get(addr) === 'done') return cache.get(addr)
    if (state.get(addr) === 'inprogress') {
      const idx = stack.indexOf(addr)
      for (let i = idx; i < stack.length; i++) {
        cache.set(stack[i], ERROR('#CYCLE!'))
        state.set(stack[i], 'done')
      }
      return ERROR('#CYCLE!')
    }
    state.set(addr, 'inprogress')
    stack.push(addr)
    const info = getCellInfo(cells, addr, parseCache)
    let val
    if (info.kind === 'literal') val = info.value
    else if (info.kind === 'formulaError') val = ERROR('#ERR!')
    else val = evalNode(info.ast, stack)
    stack.pop()
    if (state.get(addr) !== 'done') {
      cache.set(addr, val)
      state.set(addr, 'done')
    }
    return cache.get(addr)
  }

  function evaluateArgToList(node, stack) {
    if (node.type === 'range') {
      const addrs = expandRange(node)
      if (addrs === null) return [ERROR('#REF!')]
      return addrs.map((a) => evaluateCell(a, stack))
    }
    return [evalNode(node, stack)]
  }

  function evalNode(node, stack) {
    switch (node.type) {
      case 'num':
        return NUMBER(node.value)
      case 'bool':
        return { type: 'bool', value: node.value }
      case 'addr': {
        if (!node.valid) return ERROR('#REF!')
        return evaluateCell(addressKey(node.col, node.row), stack)
      }
      case 'unary': {
        const v = evalNode(node.expr, stack)
        if (v.type === 'error') return v
        const n = toNumberForArithmetic(v)
        if (n.type === 'error') return n
        const result = node.op === '-' ? -n.value : n.value
        return finiteOrDivZero(result)
      }
      case 'binop':
        return evalBinop(node, stack)
      case 'call':
        return evalCall(node, stack)
      default:
        throw new Error(`unexpected node type ${node.type}`)
    }
  }

  function evalBinop(node, stack) {
    const left = evalNode(node.left, stack)
    const right = evalNode(node.right, stack)
    const op = node.op
    if (COMPARISON_OPS.has(op)) {
      if (left.type === 'error') return left
      if (right.type === 'error') return right
      const cmp = compareValues(left, right)
      let result
      switch (op) {
        case '=':
          result = cmp === 0
          break
        case '<>':
          result = cmp !== 0
          break
        case '<':
          result = cmp < 0
          break
        case '<=':
          result = cmp <= 0
          break
        case '>':
          result = cmp > 0
          break
        case '>=':
          result = cmp >= 0
          break
      }
      return { type: 'bool', value: result }
    }
    if (left.type === 'error') return left
    const ln = toNumberForArithmetic(left)
    if (ln.type === 'error') return ln
    if (right.type === 'error') return right
    const rn = toNumberForArithmetic(right)
    if (rn.type === 'error') return rn
    let result
    switch (op) {
      case '+':
        result = ln.value + rn.value
        break
      case '-':
        result = ln.value - rn.value
        break
      case '*':
        result = ln.value * rn.value
        break
      case '/':
        if (rn.value === 0) return ERROR('#DIV/0!')
        result = ln.value / rn.value
        break
      case '^':
        result = Math.pow(ln.value, rn.value)
        break
    }
    return finiteOrDivZero(result)
  }

  function evalCall(node, stack) {
    const name = node.name
    if (!FUNCTION_NAMES.has(name)) return ERROR('#NAME?')

    if (name === 'ABS') {
      if (node.args.length !== 1) return ERROR('#ERR!')
      const vals = evaluateArgToList(node.args[0], stack)
      const v = vals[0]
      if (v.type === 'error') return v
      const n = toNumberForArithmetic(v)
      if (n.type === 'error') return n
      return finiteOrDivZero(Math.abs(n.value))
    }

    if (name === 'IF') {
      if (node.args.length !== 3) return ERROR('#ERR!')
      const condVals = evaluateArgToList(node.args[0], stack)
      const cond = toBoolean(condVals[0])
      if (cond.type === 'error') return cond
      const branch = cond.value ? node.args[1] : node.args[2]
      const branchVals = evaluateArgToList(branch, stack)
      return branchVals[0]
    }

    // SUM, MIN, MAX, COUNT, AVG: one or more arguments.
    if (node.args.length < 1) return ERROR('#ERR!')

    const flat = []
    for (const a of node.args) {
      flat.push(...evaluateArgToList(a, stack))
    }

    if (name === 'COUNT') {
      const errEntry = flat.find((v) => v.type === 'error')
      if (errEntry) return errEntry
      const count = flat.filter((v) => v.type === 'number').length
      return NUMBER(count)
    }

    const converted = []
    for (const v of flat) {
      if (v.type === 'error') return v
