 * Statically compute the set of cells each formula directly names, ranges
 * expanded, independent of what the formula evaluates to.
 */

import { parseFormula } from './parser.js'
import { addressKey, compareColRow } from './address.js'

function collect(node, out) {
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'addr':
      if (node.valid) out.push({ col: node.col, row: node.row })
      return
    case 'range': {
      if (!node.from || !node.to) return
      const colMin = Math.min(node.from.col, node.to.col)
      const colMax = Math.max(node.from.col, node.to.col)
      const rowMin = Math.min(node.from.row, node.to.row)
      const rowMax = Math.max(node.from.row, node.to.row)
      for (let c = colMin; c <= colMax; c++) {
        for (let r = rowMin; r <= rowMax; r++) {
          out.push({ col: c, row: r })
        }
      }
      return
    }
    case 'unary':
      collect(node.expr, out)
      return
    case 'binop':
      collect(node.left, out)
      collect(node.right, out)
      return
    case 'call':
      for (const a of node.args) collect(a, out)
      return
    default:
      throw new Error(`unexpected node type ${node.type}`)
  }
}

/** Returns a Map from declared address to a sorted, deduped array of address strings it names. */
export function computeDeps(cells) {
  const result = new Map()
  for (const [addr, cell] of cells.entries()) {
    if (!cell.content.startsWith('=')) {
      result.set(addr, [])
      continue
    }
    const parsed = parseFormula(cell.content.slice(1))
    if (!parsed.ok) {
      result.set(addr, [])
      continue
    }
    const raw = []
    collect(parsed.ast, raw)
    const seen = new Set()
    const unique = []
    for (const cr of raw) {
      const key = addressKey(cr.col, cr.row)
      if (!seen.has(key)) {
        seen.add(key)
        unique.push(cr)
      }
    }
    unique.sort(compareColRow)
    result.set(
      addr,
      unique.map((cr) => addressKey(cr.col, cr.row))
    )
  }
  return result
}
