{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-sMfGFe/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { evaluateSheet } from './evaluate.js'
import { computeDeps } from './deps.js'
import { formatValue } from './values.js'
import { compareColRow } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }
  const mode = args[0]

  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch (e) {
    input = ''
  }

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const sortedAddrs = [...cells.entries()]
    .sort((a, b) => compareColRow(a[1], b[1]))
    .map(([addr]) => addr)

  let output = ''
  if (mode === 'values') {
    const values = evaluateSheet(cells)
    for (const addr of sortedAddrs) {
      output += `${addr}=${formatValue(values.get(addr))}\n`
    }
  } else {
    const deps = computeDeps(cells)
    for (const addr of sortedAddrs) {
      const list = deps.get(addr)
      output += list.length > 0 ? `${addr}: ${list.join(' ')}\n` : `${addr}:\n`
    }
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
"}

