{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-x8jYvM/src/deps.js","content":"import { parseValidAddress, canonicalAddress, colLettersToNum, numToColLetters } from './address.js'

// Collects every distinct addressable cell named directly by the AST
// (ranges expanded), ordered by column then row. Any range node anywhere
// in the tree contributes its covered cells, regardless of whether it sits
// in a valid "direct function argument" position.
export function collectDeps(ast) {
  const set = new Set()
  walk(ast, set)
  return Array.from(set)
    .map((addr) => {
      const shape = parseValidAddress(addr)
      return { addr, col: colLettersToNum(shape.colLetters), row: shape.row }
    })
    .sort((a, b) => (a.col !== b.col ? a.col - b.col : a.row - b.row))
    .map((x) => x.addr)
}

function addAddressWord(word, set) {
  const shape = parseValidAddress(word)
  if (shape) set.add(canonicalAddress(shape.colLetters, shape.row))
}

function addRange(node, set) {
  const left = parseValidAddress(node.left)
  const right = parseValidAddress(node.right)
  if (!left || !right) return
  const c1 = colLettersToNum(left.colLetters)
  const c2 = colLettersToNum(right.colLetters)
  const minCol = Math.min(c1, c2)
  const maxCol = Math.max(c1, c2)
  const minRow = Math.min(left.row, right.row)
  const maxRow = Math.max(left.row, right.row)
  for (let col = minCol; col <= maxCol; col++) {
    const colLetters = numToColLetters(col)
    for (let row = minRow; row <= maxRow; row++) {
      set.add(canonicalAddress(colLetters, row))
    }
  }
}

function walk(node, set) {
  if (node === null || node === undefined) return
  switch (node.type) {
    case 'address':
      addAddressWord(node.word, set)
      break
    case 'range':
      addRange(node, set)
      break
    case 'unary':
      walk(node.operand, set)
      break
    case 'bin':
      walk(node.left, set)
      walk(node.right, set)
      break
    case 'pow':
      walk(node.base, set)
      walk(node.exp, set)
      break
    case 'call':
      for (const arg of node.args) walk(arg, set)
      break
    default:
      break
  }
}
"}

