/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import fs from 'node:fs'
import { parseSheet, sortedAddresses, SheetError } from './sheet.js'
import { parseFormula } from './parser.js'
import { collectDeps } from './deps.js'
import { Evaluator } from './evaluator.js'
import { formatNumber } from './format.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }
  const mode = args[0]

  const input = fs.readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(e.message)
      return
    }
    throw e
  }

  const addrs = sortedAddresses(cells)
  const lines = []

  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const addr of addrs) {
      const value = evaluator.getCellValue(addr)
      lines.push(`${addr}=${formatValue(value)}`)
    }
  } else {
    for (const addr of addrs) {
      const cell = cells.get(addr)
      let depAddrs = []
      if (cell.content.startsWith('=')) {
        const ast = parseFormula(cell.content.slice(1))
        if (ast !== null) depAddrs = collectDeps(ast)
      }
      lines.push(depAddrs.length > 0 ? `${addr}: ${depAddrs.join(' ')}` : `${addr}:`)
    }
  }

  process.stdout.write(lines.map((l) => l + '\n').join(''))
}

function formatValue(value) {
  switch (value.t) {
    case 'number':
      return formatNumber(value.v)
    case 'error':
      return value.v
    case 'bool':
      return value.v ? 'TRUE' : 'FALSE'
    case 'text':
      return value.v
    default:
      return String(value.v)
  }
}

main()
"}

