import { parseURIReference, normalizeParsed, resolveReference, serialize } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function splitRecords(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }
  return lines
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
    return
  }
  const mode = args[0]

  const input = readStdin()
  const records = splitRecords(input)

  const outLines = []

  for (let i = 0; i < records.length; i++) {
    const lineNo = i + 1
    const record = records[i]

    try {
      if (mode === 'normalize') {
        const parsed = parseURIReference(record)
        const normalized = normalizeParsed(parsed)
        outLines.push(serialize(normalized))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) {
          fail(`line ${lineNo}: expected a base and a reference`)
          return
        }
        const baseStr = record.slice(0, spaceIdx)
        const refStr = record.slice(spaceIdx + 1)

        const base = parseURIReference(baseStr)
        if (base.scheme === undefined) {
          fail(`line ${lineNo}: the base has no scheme`)
          return
        }
        const ref = parseURIReference(refStr)

        const resolved = resolveReference(base, ref)
        const normalized = normalizeParsed(resolved)
        outLines.push(serialize(normalized))
      }
    } catch (err) {
      if (err && err.component) {
        fail(`line ${lineNo}: the ${err.component} has a truncated percent-encoding`)
        return
      }
      throw err
    }
  }

  const output = outLines.length === 0 ? '' : outLines.join('\n') + '\n'
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

