  const args = process.argv.slice(2)
  const mode = args.length === 1 ? args[0] : null
  if (mode !== 'rounds' && mode !== 'tally') {
    fail('usage: cli.js rounds|tally')
  }

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      if (err.line !== undefined) {
        fail(`line ${err.line}: ${err.message}`)
      } else {
        fail(err.message)
      }
    }
    throw err
  }

  const { rounds, winner } = runElection(election)

  const lines = []
  if (mode === 'rounds') {
    rounds.forEach((round, i) => {
      lines.push(formatRound(i + 1, round))
      if (round.eliminated !== null) {
        lines.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    lines.push(`rounds ${rounds.length}`)
  }

  lines.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(lines.join('\n') + '\n')
  process.exit(0)
}

main()
